(window.__BOOKS=window.__BOOKS||{})["e_supplices"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\">Эфра, мать <span class=\"ch\" data-ch=\"tesey\">Тесея</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Хор — аргосские матери и их служанки</span>"],["person","<span class=\"pn\">Тесей, афинский царь</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Адраст, аргосский царь</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Герольд</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Вестник</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Эвадна, вдова Капанея</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Ифит, старик аргосец, ее отец</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Сыновья павших под Фивами</span>"],["person","<span class=\"pn\">Афина</span> <span class=\"act-no\">(III)</span>"],["place","Действие — в Элевсине."],["act","Пролог","a1",""],["scene","Явление первое","s1",1,1],["sd","Задняя декорация изображает фронтон элевсинского храма Деметры. Справа, позади храма и над ним, скала. На ступенях алтаря всех выше <span class=\"ch\" data-ch=\"efra\">Эфра</span> в царской одежде; перед ней хор — ближе матери, ниже служанки, все в трауре: в знак мольбы женщины протягивают к <span class=\"ch\" data-ch=\"efra\">Эфре</span> оливковые ветви с намотанной на них шерстью. Алтарь курится. В стороне лежит прямо на земле <span class=\"ch\" data-ch=\"adrast\">Адраст</span>, прикрытый с головою темным плащом, около него стоят отроки."],["sp","<span class=\"ch\" data-ch=\"efra\">Эфра</span>"],["v","Деметра, ты, которая блюдешь<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,1,0,0],["v","Очажный огонь Элевсиса, и вы,",0,1,0,0],["v","Другие боги с нею, я молю вас",0,1,0,0],["v","О счастье для себя и для <span class=\"ch\" data-ch=\"tesey\">Тесея</span>:",0,2,0,0],["v","Храните нам Афины и Трезен,<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,3,0,0],["v","Откуда, верен Локсию, Эгею",0,4,0,0],["v","Средь роскоши взрастивший нас отец",0,5,0,0],["v","Свою Пандиониду отдал <span class=\"ch\" data-ch=\"efra\">Эфру</span>.",0,6,0,0],["sd","Пауза."],["v","К молитве нас зовет печальный вид",0,7,0,0],["v","Старух, которые, покинув Аргос",0,8,0,0],["v","И очаги свои, к моим ногам",0,9,0,0],["v","С оливами молящих припадают.",0,10,0,1],["v","Несчастье их постигло семерых.",0,10,0,0],["v","Убитыми у семивратных Фив",0,11,0,0],["v","Еще лежат их сыновья-герои,",0,12,0,0],["v","Куда <span class=\"ch\" data-ch=\"adrast\">Адраст</span> Аргосский их привлек",0,13,0,0],["v","За долею Эдипова наследства…",0,14,0,0],["v","О зяте мысль Адрастова была,",0,15,0,0],["v","Изгнаннике кадмейском — Полинике.",0,16,0,0],["v","Владыки Фив надменно не дают",0,17,0,0],["v","Их матерям на поле брани павших",0,18,0,0],["v","Похоронить, закон богов презревши.",0,19,0,0],["v","Вот он, Адраст, — молений тяготу",0,20,0,1],["v","У ног моих он с матерями делит,",0,20,0,0],["v","И слезы по лицу его бегут,",0,21,0,0],["v","Едва поход свой вспомнит злополучный:",0,22,0,0],["v","Не в добрый час поход он начал. К нам",0,23,0,0],["v","Теперь мольба его, чтобы <span class=\"ch\" data-ch=\"tesey\">Тесея</span>",0,24,0,0],["v","Уговорить и чтобы царь иль словом,",0,25,0,0],["v","Иль силою упорство их сломил",0,26,0,0],["v","И возвратить тела велел. Так вот",0,27,0,0],["v","Афины им зачем и сын мой нужны.",0,28,0,0],["v","Уж сожжена на алтаре и жертва",0,29,0,0],["v","За пахарей средь нив, где в первый раз<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,30,0,1],["v","Щетиною колосья поднялись…",0,31,0,0],["v","Но силы нет листов оливы слабой",0,32,0,0],["v","Мне цепь порвать. Я не могу уйти",0,33,0,0],["v","От очага богинь. Седин их жалко.",0,34,0,0],["v","Оплакав жен осиротелых, я",0,35,0,0],["v","Заклятий их боюсь. Я уж послала",0,36,0,0],["v","<span class=\"ch\" data-ch=\"tesey\">Тесея</span> звать из города. Пускай",0,37,0,0],["v","Печальных душ ушлет отсюда язву",0,38,0,0],["v","Иль цепи их молений разорвет",0,39,0,0],["v","Он правдою дерзания. Жены",0,40,0,1],["v","Лишь силою мужей советы властны.",0,41,0,0],["scene","Вступительная песнь хора","s2",1,2],["sd","Матери"],["str","Строфа I"],["v","Старуха, плача, старухе",0,42,0,0],["v","В пыли целует колени:",0,43,0,0],["v","Отдай сыновей ей, отдай,",0,44,0,0],["v","Злодея казни, царица!",0,45,0,0],["v","Убитые в поле лежат,",0,46,0,0],["v","А звери в полях так жадны…",0,47,0,0],["str","Антистрофа I"],["v","О, сжалься: слезы так едки,",0,48,0,0],["v","Пути их залиты кровью,",0,49,0,0],["v","Глубоки следы от ногтей, —",0,50,0,1],["v","А ложе мертвых так пусто;",0,51,0,0],["v","Напрасно я милых ищу:",0,52,0,0],["v","Их нет и в черной могиле.",0,53,0,0],["str","Строфа II"],["v","Сына и ты когда-то давно",0,54,0,0],["v","Царю принесла ведь на ложе,",0,55,0,0],["v","Где вас сливала ласка…",0,56,0,0],["v","Нас ты поймешь. Придай же",0,57,0,0],["v","Думы своей горьким;",0,58,0,0],["v","Муки те, муки вспомнив,",0,59,0,0],["v","Сыну вели спасти нас:",0,60,0,1],["v","Мертвых детей, царица,",0,60,0,0],["v","Пусть матерям",0,61,1,0],["v","Жадным вернет их объятьям!",0,62,0,0],["str","Антистрофа II"],["v","Нет, не мольба, несчастье",0,63,0,0],["v","К ступеням прибило нас этим.",0,63,0,0],["v","Жертвы богиням нету",0,64,0,0],["v","В наших руках молящих;",0,65,0,0],["v","Правда одна с нами…",0,66,0,0],["v","Мать блаженная, горькой,",0,66,0,0],["v","Верю я, ты поможешь:",0,67,0,0],["v","Царь за мои страданья",0,68,0,0],["v","Матери даст",0,69,1,0],["v","Сына сложить хоть останки.",0,70,0,1],["sd","Служанки (с мимикой и ритмическими движениями более страстного характера)"],["str","Строфа III"],["v","Вы теперь, вы, о рабыни… Гей!",0,70,0,0],["v","Заводите вы плач свой… Иу!",0,71,0,0],["v","Бей себя в грудь… Иу!",0,72,0,0],["v","Вы сострадайте страждущей,",0,73,0,0],["v","Вы плачьте вместе с плачущей,",0,73,0,0],["v","Вмыкайтесь в погребальный вы",0,74,0,0],["v","И мрачный хоровод!",0,75,0,0],["v","Чтоб белая ланита",0,76,0,0],["v","Алела под ногтем.",0,76,0,0],["v","Иу! Отраден мертвым",0,77,0,0],["v","Печальный наш убор.",0,78,0,0],["str","Антистрофа III"],["v","Страшные волны мучения,",0,79,0,0],["v","Неутешная снова печаль",0,80,0,1],["v","Носит и кружит нас…",0,80,0,0],["v","Глаза у нас — как волнами",0,81,0,0],["v","Росимая скала… Иу!",0,82,0,0],["v","Увы! Судьбина женская!",0,82,0,0],["v","В слезах исхода нет",0,83,0,0],["v","Тоске по мертвым детям:",0,84,0,0],["v","Бессмертна ты, тоска!",0,85,0,0],["v","Но если смерть — забвенье,",0,85,0,0],["v","Благословлю и смерть.",0,86,0,0],["scene","Явление второе","s3",1,3],["sd","Те же и <span class=\"ch\" data-ch=\"tesey\">Тесей</span> с небольшой свитой приходит слева."],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","еще не видя алтаря"],["v","Я слышал гул от стонов, от ударов",0,87,0,0],["v","По персям — и безрадостный напев",0,87,0,0],["v","Узнал я погребальный. Стены храма",0,88,0,0],["v","Гудели вслед, и страх нас окрылил.",0,89,0,0],["v","Не с матерью ль несчастье? Из чертога",0,90,0,1],["v","Она ушла давно, и я за ней…",0,90,0,0],["sd","(Видит мать, хоры и <span class=\"ch\" data-ch=\"adrast\">Адраста</span>.)"],["v","Ба…",0,91,0,0],["v","А это что ж? Что вижу я? Царица",0,92,0,0],["v","На ступенях алтарных — жены с ней",0,93,0,0],["v","Безвестные, и каждое движенье",0,94,0,0],["v","Их говорит о горе, и из глаз",0,95,0,0],["v","Их старческих катятся слезы наземь.",0,95,0,0],["v","Их волосы обриты, ризы их",0,96,0,0],["v","Непраздничного вида… Ты, родная,",0,97,0,0],["v","Нам объясни, что значит это, — я ж,",0,98,0,0],["v","Я весь — одно вниманье и тревога…",0,99,0,0],["sp","<span class=\"ch\" data-ch=\"efra\">Эфра</span>"],["v","То матери, мой сын, семи вождей,",0,100,0,1],["v","Под Фивами убитых: зорко круг их",0,101,0,0],["v","Нас оцепил, ты видишь, и олив",0,102,0,0],["v","Они из рук, моля, не выпускают.",0,103,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","А это кто ж там плачет, распростерт?",0,104,0,0],["sp","<span class=\"ch\" data-ch=\"efra\">Эфра</span>"],["v","Аргосского <span class=\"ch\" data-ch=\"adrast\">Адраста</span> называешь.",0,105,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","А мальчики? Иль дети этих жен?",0,106,0,0],["sp","<span class=\"ch\" data-ch=\"efra\">Эфра</span>"],["v","Нет, сыновья убитых под Кадмеей.",0,107,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О чем же нас молить они пришли?",0,108,0,0],["sp","<span class=\"ch\" data-ch=\"efra\">Эфра</span>"],["v","Я слышала, тебе ж пускай расскажут.",0,109,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","к <span class=\"ch\" data-ch=\"adrast\">Адрасту</span>"],["v","Ты там, плащом покрытый, объясни,",0,110,0,1],["v","Но сняв покров с лица и без стенаний.",0,111,0,0],["v","Одна стезя для мысли — наш язык…",0,112,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["dir","открываясь"],["v","Благовенчанный царь земли Афинской,",0,113,0,0],["v","К тебе моя и к городу мольба!",0,114,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О чем мольба? Чего от нас желаешь?",0,115,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["dir","тихо"],["v","Ты знаешь, царь, мой пагубный поход.",0,116,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Да, шумом вы наполнили Элладу.",0,117,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Цвет Аргоса остался там, увы!",0,118,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О, бич войны тяжел и беспощаден!",0,119,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Я возвратить мне трупы их просил.",0,120,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Их твой герольд просил, слуга Гермеса?",0,121,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","…Счастливо враг посольство отклонил.",0,122,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Чем подкреплен отказ их беззаконный?",0,123,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Успех пьянит. В успехе сила их…",0,124,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","От нас чего ж ты просишь?.. Иль совета?",0,125,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["dir","простирая руки"],["v","Царь! Вызволи аргосские тела!",0,126,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","А Аргос ваш? Иль даром вы хвалились?",0,127,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Увы!.. Одна надежда на тебя…",0,128,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Ты от себя, иль Аргосом ты послан?",0,129,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Все молим мы: отдай нам мертвецов.",0,130,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","А семь дружин из-за чего ж гонял ты?",0,131,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Двоим зятьям в угоду был поход.",0,132,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Из Аргоса зятья, конечно, были?",0,133,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Нет, женихов аргосских не нашлось.",0,134,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","И увели царевен чужестранцы?..",0,135,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Да. Полиник Фиванский и Тидей…",0,136,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","А почему ж на этих пал твой выбор?",0,137,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Загадкою нас спутал Аполлон.",0,138,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Кого же он давал в мужья девицам?",0,139,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Льва для одной, кабана — для другой…",0,140,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","И как же ты истолковал оракул?",0,141,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Раз ночью к нам два путника пришло.",0,142,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Но кто ж и кто? Ты говоришь, что двое…",0,143,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Гляжу — борьба: Тидей и Полиник.",0,144,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","И в них зверей предсказанных узнал ты?",0,145,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Борцы зверей напоминали мне.",0,146,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Но что же их от очагов прогнало?",0,147,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Сородича, о царь, Тидей убил.",0,148,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","А Полиник за что ушел в изгнанье?",0,149,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","От слов отца пророческих бежал,",0,150,0,1],["v","Чтобы не стать убийцей Этеокла…<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,150,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Он поступил разумно, если так…",0,151,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","…И обделен заглазно был в Кадмее.",0,152,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Что ж? Или брат наследство захватил?",0,153,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Я выступил в защиту, и разбит я…",0,154,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","после паузы"],["v","…Не выслушав гадателей сперва.",0,155,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["dir","опуская голову"],["v","Не береди, о царь, горящей раны.",0,156,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Глагол небес тебя не окрылил?",0,157,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["dir","закрывая лицо руками"],["v","О, хуже, царь! Амфиарай был против.<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,158,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","И так легко ты этим пренебрег?",0,159,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Нас юношей увлек шумливый пыл.",0,160,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Отважный дух, не крепкий ум тобой",0,160,0,0],["v","Руководил. Так гибло много славных.",0,161,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","О лучший вождь Эллады, царь Афин,",0,162,0,0],["v","Мне совестно, Тесей, перед тобой",0,163,0,0],["v","Склонять свои седины и колени",0,164,0,0],["v","Охватывать, моля, твои….Давно ль",0,165,0,0],["v","Я тоже был счастливый царь, но сила",0,166,0,0],["v","Несчастия согнула нас: вели",0,167,0,0],["v","Вернуть тела аргосские и сжалься",0,168,0,0],["v","Над бедами, над горем матерей,",0,169,0,0],["v","Над старостью, столь безнадежно сирой…",0,170,0,1],["v","Они едва волочат ноги, царь,",0,170,0,0],["v","От дряхлости, но этот путь далекий",0,171,0,0],["v","Не в храм их вел на богомолье, нет:",0,171,0,0],["v","Похоронить детей их молят руки,",0,172,0,0],["v","Тех сыновей, от коих для себя",0,172,0,0],["v","Они — давно — услуги этой ждали.",0,173,0,0],["v","От бедности богатый, от беды",0,173,0,0],["v","Счастливый да не отклоняет взора!",0,174,0,0],["v","И если кто судьбою взыскан, пусть",0,174,0,0],["v","О жребии людей непостоянном",0,175,0,0],["v","Среди своей удачи помнит, пусть",0,175,0,0],["v","Сиянье солнца свежей бодрой волей",0,176,0,0],["v","Счастливцу наполняет сердце.",0,176,0,0],["v","Тень",1,176,0,0],["v","Ведь и его покроет тоже… Счастье",0,177,0,0],["v","Капризно отвернется, и тогда",0,177,0,0],["v","Погаснет радость бодрого деянья, —",0,178,0,0],["v","Без бодрости ж — победы нет.",0,178,0,0],["v","……………………….<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,179,0,0],["v","Певец,",1,179,0,0],["v","Когда свои слагает гимны, должен",0,180,0,1],["v","Их радостно творить. Когда печаль",0,180,0,0],["v","Своя его гнетет, скажи, откуда ж",0,181,0,0],["v","Возьмет он сил развеселить других?",0,182,0,0],["v","Но, может быть, ты спросишь: \"Край Пелопа",0,183,0,0],["v","Был на пути — зачем же этот груз<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,184,0,0],["v","В Афины ты приносишь?\" Вот что должен",0,185,0,0],["v","Я отвечать тебе: спартанцы, царь,",0,186,0,0],["v","Бесчувственны, они полны коварства.",0,187,0,0],["v","Все города другие слабы. Ваш",0,188,0,0],["v","Один бы с делом справился. Афины",0,189,0,0],["v","Сочувствуют несчастью, ты ж хоть юн,",0,190,0,1],["v","Но доблестен; а сколько погибало",0,190,0,0],["v","Уж городов без сильного вождя.",0,191,0,0],["sp","Корифей"],["v","И я свое прибавлю слово: к сердцу",0,192,0,0],["v","Прими, Тесей, печальный жребий наш.",0,193,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Пришлось и мне подобную твоей",0,194,0,0],["v","Когда-то речь держать, я помню, в споре.",0,195,0,0],["v","Противник мой стоял на том, что зла",0,196,0,0],["v","Гораздо больше, чем добра. С обратным",0,197,0,0],["v","Я положеньем выступал, — старался",0,198,0,0],["v","Я утвердить за благом перевес,",0,199,0,0],["v","Иначе б мир как уцелел доселе?",0,200,0,1],["v","Хвала тому бессмертному, который,<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,200,0,0],["v","Над дикостью звериной нас подъяв,",0,201,0,0],["v","Дал разум нам божественный, вещанья",0,202,0,0],["v","Дал языку и голос окрылил",0,203,0,0],["v","Осмысленною речью. Меж богов",0,204,0,0],["v","Хвала тому, кто в пищу нам плоды",0,205,0,0],["v","Определил, небесною росою",0,205,0,0],["v","Взращая семена и небо нам",0,206,0,0],["v","Сухое орошая, кто зимою",0,207,0,0],["v","Дает нам одеянье, кто моря",0,208,0,0],["v","Нас научил переплывать, чужие",0,209,0,0],["v","Выменивать товары. А когда",0,210,0,1],["v","Загадкою мы смущены, гадатель",0,211,0,0],["v","Является на помощь и полет",0,212,0,0],["v","Толкует нам пернатых иль огня",0,213,0,0],["v","Пророческие знаки. Это бог",0,214,0,0],["v","Порядок нам такой установил.",0,215,0,0],["v","Но люди есть, которые, гордыне",0,216,0,0],["v","Дав ослепить рассудок, быть умней",0,217,0,0],["v","Богов хотят. И ты из их десятка,",0,218,0,0],["v","Должно быть, царь <span class=\"ch\" data-ch=\"adrast\">Адраст</span>, ты — ложный ум.",0,219,0,0],["v","Ты дочерей за чужестранцев выдал,",0,220,0,1],["v","Оракулу послушный; значит, ты",0,220,0,0],["v","В богов-то верил, если даже чистый",0,221,0,0],["v","Не побоялся дом свой запятнать,",0,222,0,0],["v","Внеся в него грехи чужие. Умный",0,223,0,0],["v","С невинностью порока не дерзнет",0,223,0,0],["v","Соединить: он только чистым руку",0,224,0,0],["v","Отважится подать, а кто судьбу",0,225,0,0],["v","С преступными связал, будь даже сердцем",0,226,0,0],["v","Он чист, суда богов тот трепещи!",0,226,0,0],["v","Его порок в паденье увлекает.",0,227,0,0],["v","Но далее?.. Когда ты начинал",0,228,0,0],["v","Войну и речь гадателей угрозой",0,229,0,0],["v","Над Аргосом звучала, о богах",0,230,0,1],["v","Подумал ли ты, царь? Не ты ли в бездну",0,230,0,0],["v","Увлек свои войска?",0,231,0,0],["v","Ты говоришь,",1,231,0,0],["v","Что молодежь тебя сбивала: битвы",0,232,0,0],["v","Честолюбивый требовал их пыл.",0,232,0,0],["v","Он о правах и пользе граждан думать",0,233,0,0],["v","Не позволял тебе. Из молодых",0,234,0,0],["v","Вождей один стремился к блеску, властью",0,234,0,0],["v","Другой пленен — простора для своих",0,235,0,0],["v","Искал страстей, а третий жаждал денег,",0,236,0,0],["v","Но каково народу, это их",0,236,0,0],["v","Не занимало слишком. В государстве",0,237,0,0],["v","Три класса есть: во-первых, богачи,",0,238,0,0],["v","Для города от них нет пользы, им бы",0,238,0,0],["v","Лишь для себя побольше. Но опасны",0,239,0,0],["v","И бедняки и чернь, когда свое",0,240,0,1],["v","С угрозою подъемлют на имущих",0,240,0,0],["v","Отравленное жало, подговорам",0,241,0,0],["v","Послушная витий. Лишь средний класс",0,242,0,0],["v","Для города опора; он законам",0,243,0,0],["v","Покорствует и власти.",0,244,0,0],["v","Рассуди ж,",1,244,0,0],["v","Неужто мне в союз вступать с тобою?",0,245,0,0],["v","Да что же я афинянам скажу?",0,246,0,0],["v","Иди своей дорогой. — Если плохо",0,247,0,0],["v","Придумал, так последствия неси",0,248,0,0],["v","Ты сам своей придумки. Мы при чем же?",0,249,0,0],["sp","Корифей"],["v","Был дерзок шаг, что ж делать? Молодежь!",0,250,0,1],["v","На старике ль вся тяжесть искупленья?",0,250,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Я не судьи искал, афинский царь,",0,251,0,0],["v","Когда к тебе я шел: бедой застигнут,",0,252,0,0],["v","Надеялся на помощь я — бранить,",0,253,0,0],["v","Корить ли нас — излишнее. Не хочешь",0,254,0,0],["v","Ты нам помочь, что ж делать! Спорить тут,",0,255,0,0],["v","Пожалуй, незачем… Идемте ж прочь,",0,255,0,0],["v","Вы, старые… Блестящую листву",0,256,0,0],["v","Оливковых ветвей своих покиньте",0,257,0,0],["v","На ступенях алтарных. Пусть листы",0,258,0,0],["v","Касаются их глянцем. Призываю",0,259,0,0],["v","В свидетели богов я. Землю я",0,260,0,1],["v","В свидетели беру, Деметры факел",0,260,0,0],["v","Богини призываю, Солнца свет,",0,261,0,0],["v","Что были нам моленья бесполезны.",0,261,0,0],["sp","Корифей"],["v","Итак, домой, с отчаяньем в сердцах,",0,262,0,0],["v","С обидою бессильных слез, обратно!",0,262,0,0],["sd","(К <span class=\"ch\" data-ch=\"efra\">Эфре</span>.)"],["v","[И ты дерзнешь по брошенным ветвям",0,263,0,0],["v","Оливы бесполезной снизойти,",0,263,0,0],["v","Алтарные ступени попирая?!",0,264,0,0],["v","А сила общей крови? Иль Питфей,",0,264,0,0],["v","Твой царственный отец, не] сын Пелопа,<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,265,0,0],["v","Чей остров нас взрастил? В нас кровь одна,",0,265,0,0],["v","И ты, царица <span class=\"ch\" data-ch=\"efra\">Эфра</span>, нас, старух,",0,266,0,0],["v","Решишься прав лишить и оттолкнуть,",0,266,0,0],["v","А бог на что ж? Нора спасает зверя",0,267,0,0],["v","И божий дом — молящего раба…",0,267,0,0],["v","Когда нуждой застигнут город, разве",0,268,0,0],["v","Не в городе другом его спасенье?",0,268,0,0],["v","Блага земли не прочны; до конца",0,269,0,0],["v","Не остается счастье смертным, <span class=\"ch\" data-ch=\"efra\">Эфра</span>.",0,270,0,1],["sd","Хор матерей (спускаясь медленно и утомленно по ступеням алтаря)"],["v","Очаг Деметры оставьте и, горькие, встаньте,",0,270,0,0],["v","Встаньте, чтобы пасть к его коленям,",0,271,0,0],["v","Пасть и прижаться, моля. Пусть из Кадмеи,",0,272,0,0],["v","Пусть нам детей он вернет убитых.",0,273,0,0],["sd","(К служанкам.)"],["v","Ах! Я падаю! Вы,",0,273,2,0],["v","Вы, молодые рабыни,",0,274,2,0],["v","Возьмите, несите, ведите, руке",0,275,2,0],["v","Дряхлой будьте опорой!",0,276,2,0],["sd","(Служанки и матери обнимают колени <span class=\"ch\" data-ch=\"tesey\">Тесея</span>.)"],["v","Милый, о светлый, о вождь!",0,276,0,0],["v","Видишь — колени с мольбой твои обняла я!",0,277,0,0],["v","Я к руке припадаю, к ланите влекусь;",0,278,0,0],["v","Сжалься: как нищие мы,",0,279,0,0],["v","Бродим с тоской по чужбине, и песни",0,280,0,1],["v","Слезные реки за нами идут погребальной.",0,280,0,0],["v","О, милосердье для наших детей!",0,281,0,0],["v","Сын мой, ужели ж ты трупы",0,282,0,0],["v","В поле так и оставишь добычей для птиц?",0,283,0,0],["v","Трупы таких же, как ты, юных, могучих?",0,283,0,0],["v","Молим тебя… Слезы, гляди, это слезы,",0,284,0,0],["v","С прахом смешалися косы… О, мира!",0,285,0,0],["v","Дай им, Тесей, только мира могилы!",0,286,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","обращаясь к матери, которая остается на ступенях алтаря"],["v","Ты плачешь, мать? Фатою ты глаза",0,286,0,0],["v","Прикрыла? Иль тебе так жалки стоны",0,287,0,0],["v","Тоскующих? Смутилось сердце в нас,",0,288,0,0],["v","О, подними же белую главу:",0,289,0,0],["v","У очага богов не надо плакать.",0,290,0,1],["sp","<span class=\"ch\" data-ch=\"efra\">Эфра</span>"],["v","Увы!",0,290,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О мать! Те слезы не твои.",0,291,0,0],["sp","<span class=\"ch\" data-ch=\"efra\">Эфра</span>"],["v","О, как они несчастны.",0,292,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Но не ты же?",1,292,0,0],["sp","<span class=\"ch\" data-ch=\"efra\">Эфра</span>"],["v","Дерзну ль с тобой о чести говорить",0,292,0,0],["v","Тесеевой и об афинской чести?",0,293,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Да, говори! Из женских уст порой",0,294,0,0],["v","Прекрасные советы выходили.",0,294,0,0],["sp","<span class=\"ch\" data-ch=\"efra\">Эфра</span>"],["v","Уж и сама не знаю. Трепещу",0,295,0,0],["v","Нести на свет таимое глубоко.",0,296,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","с ласковым укором"],["v","Но, может быть, напротив — ты должна<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,296,0,0],["v","Стыдиться, что таишь от сына благо?",0,297,0,0],["sp","<span class=\"ch\" data-ch=\"efra\">Эфра</span>"],["v","Нет, не хочу молчать, чтобы потом",0,298,0,0],["v","Раскаяньем терзаться. Если женам",0,298,0,0],["v","Высокая и не пристала речь,",0,299,0,0],["v","Не жертвовать же правдой страху нам,",0,300,0,1],["v","Что кто-нибудь осудит нас за дерзость!",0,300,0,0],["v","Остерегись, не делаешь ли ты",0,301,0,0],["v","Ошибки, царь <span class=\"ch\" data-ch=\"tesey\">Тесей</span>, когда не хочешь",0,302,0,0],["v","Восстановить их честь. Я не боюсь,",0,303,0,0],["v","Чтоб в чем другом <span class=\"ch\" data-ch=\"tesey\">Тесея</span> упрекнули.",0,303,0,0],["v","Когда б еще вступиться должен был",0,304,0,0],["v","Ты за людей, обиды не видавших,",0,305,0,0],["v","Мои слова излишни были 6. Здесь",0,306,0,0],["v","Я говорю о славном деле. Страха",0,306,0,0],["v","Не знаю я, когда тебя зову",0,307,0,0],["v","Против мужей, которые мешают",0,308,0,0],["v","Убитому быть погребенным; силой",0,309,0,0],["v","Вступись за них и эллинский закон",0,310,0,1],["v","От дерзких рук спаси, <span class=\"ch\" data-ch=\"tesey\">Тесей</span>. В охране",0,311,0,0],["v","Божественных законов вся надежда,",0,312,0,0],["v","Вся сила городов.",0,313,0,0],["v","Дождаться б ты слов чьих-либо хотел,",0,314,0,0],["v","Что трусость отклонила от венца",0,315,0,0],["v","Тесееву десницу: с диким вепрем",0,316,0,0],["v","Он не боялся драться, а едва<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,317,0,0],["v","Блеснула медь копья и шлем метнулся",0,318,0,0],["v","В глаза ему, он оробел… О нет,",0,319,0,0],["v","Я родила другим тебя.",0,320,0,1],["v","Афины —",1,320,0,0],["v","Твоя отчизна, если дерзость их",0,320,0,0],["v","Кто обличать решится, отвечают",0,321,0,0],["v","Сверканьем взгляда гордого. В боях",0,322,0,0],["v","Паллады город крепнет. Не указ",0,323,0,0],["v","Те города ему, что из потемок",0,323,0,0],["v","На божий свет поднять не смеют глаз.",0,324,0,0],["v","Ты, кровь моя, без помощи оставишь",0,325,0,0],["v","Несчастных матерей и без могилы",0,326,0,0],["v","Убитого солдата? За тебя",0,326,0,0],["v","Не трепещу, когда в походе правда",0,327,0,0],["v","Тебя ведет. Фиванцам улыбалось",0,328,0,0],["v","Покуда счастье, точно.",0,329,0,0],["v","Но различно",1,329,0,0],["v","Ведь падают и кости. И богов",0,330,0,1],["v","Нередко мысль удачи наши рушит.",0,331,0,0],["sp","Корифей"],["v","Болезнуя о сыне, и меня",0,332,0,0],["v","В речах ты не забыла. Две отрады!",0,333,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Слова мои <span class=\"ch\" data-ch=\"adrast\">Адрасту</span> и теперь",0,334,0,0],["v","Я повторить готов насчет ошибок,",0,335,0,0],["v","Которые его сгубили, мать!",0,336,0,0],["v","Но и твои внушения, родная,",0,337,0,0],["v","Не прозвучали даром.",0,338,0,0],["v","Не пристала",1,338,0,0],["v","<span class=\"ch\" data-ch=\"tesey\">Тесею</span> осторожность — это правда.",0,339,0,0],["v","Сам эллинов я приучил во мне",0,340,0,1],["v","Карателя злодейства видеть, где бы",0,340,0,0],["v","Оно ни притаилось. И от дела",0,341,0,0],["v","Мне не уйти.",0,342,0,0],["v","Уж если ты, забыв",1,342,0,0],["v","Свой вечный страх за сына, посылаешь",0,342,0,0],["v","Его на праздник ратный, и притом",0,343,0,0],["v","Не первая ль? От зависти людской",0,344,0,0],["v","Чего ж нам ждать?",0,345,0,0],["v","Итак, за дело! Мертвых",1,345,0,0],["v","Уговорю вернуть им. Но в запасе",0,345,0,0],["v","И меч у нас. На милость божью тоже",0,346,0,0],["v","Теперь-то есть надежда… Только воля",0,347,0,0],["v","Афинского народа на поход<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,347,0,0],["v","Должна быть нам. Хоть за моей, я знаю,",0,348,0,0],["v","Пойдут они, но если обсудить",0,349,0,0],["v","Я дам им это дело, то охотней",0,350,0,1],["v","Они пойдут.",0,350,0,0],["v","И разве я не сам",1,350,0,0],["v","Освободил народ и граждан созвал",0,351,0,0],["v","Из подданных?",0,352,0,0],["v","Теперь пускай со мной",1,352,0,0],["v","<span class=\"ch\" data-ch=\"adrast\">Адраст</span> идет в народное собранье.",0,353,0,0],["v","Мои слова подействуют сильней",0,354,0,0],["v","При зрелище несчастного.",0,355,0,0],["v","Решат —",1,355,0,0],["v","С отборною меня дружиной ждите!",0,355,0,0],["v","Посмотрим, что ответит нам тогда",0,356,0,0],["v","Фиванский вождь на просьбу выдать мертвых.",0,357,0,0],["sd","(К хору.)"],["v","Вы, старые, ограду из ветвей",0,358,0,0],["v","Священную раздвиньте. В дом Эгея",0,359,0,0],["v","Я отведу родимую, руки",0,360,0,1],["v","Ее коснувшись с лаской.",0,361,0,0],["v","Злополучен,",1,361,0,0],["v","Кто послужить родителям не мог:",0,362,0,0],["v","Между людьми залога нет вернее —",0,363,0,0],["v","Что дал отцу, все с сына ты вернешь.",0,364,0,0],["sd","(Уходит со свитой, <span class=\"ch\" data-ch=\"adrast\">Адрастом</span> и <span class=\"ch\" data-ch=\"efra\">Эфрой</span> в домашнюю сторону.)"],["scene","Первый музыкальный антракт","s4",1,4],["sp","Хор"],["str","Строфа I"],["v","Коней питающий, Аргос родимый наш,",0,365,0,0],["v","Слышал ли слово ты, слышал ли царское?",0,366,0,0],["v","Правдой божественной слово венчанное,",0,367,0,0],["v","Это — для Аргоса слово великое.",0,368,0,0],["str","Антистрофа I"],["v","Если ж победою смелость венчается,",0,369,0,0],["v","Если из праха он вырвет для матери",0,370,0,1],["v","Эту жемчужину, краю Инахову",0,370,0,0],["v","Витязя славного нам не любить тогда?<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,371,0,0],["str","Строфа II"],["v","Светлый венец народу —",0,371,0,0],["v","Если за Правду спорит,",0,372,0,0],["v","Милость навек стяжает.",0,373,0,0],["v","Чем-то решат Афины?",0,373,0,0],["v","Помощь они нам дадут ли?",0,374,0,0],["v","И сыновья",0,375,2,0],["v","Мир в гробу обретут ли?",0,375,0,0],["str","Антистрофа II"],["v","О, защити кормивших,",0,376,0,0],["v","Город Паллады, сжалься!",0,376,0,0],["v","Переступать народных",0,377,0,0],["v","Прав не давай людям!",0,378,0,0],["v","Ты не пособник злодею!",0,378,0,0],["v","Правде одной",0,379,2,0],["v","Ты в нужде помогаешь.",0,380,0,1],["act","Действие второе","a2","II"],["scene","Явление третье","s5",2,5],["sd","С домашней стороны является <span class=\"ch\" data-ch=\"tesey\">Тесей</span> со свитой. Он вооружен и с жезлом. За ним герольд и <span class=\"ch\" data-ch=\"adrast\">Адраст</span>, тоже со свитой."],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","Герольду"],["v","Немало стран с тобою обошло",0,380,1,0],["v","Афинское решенье.",0,381,1,0],["v","Послужи нам",1,381,0,0],["v","И за чертой Асопа. Там тирану",0,382,1,0],["v","Надменному Кадмеи вот слова",0,383,1,0],["v","Тесеевы: \"Отдай для погребенья",0,384,1,0],["v","Аргосские тела ему. А наш",0,385,1,0],["v","Твоей услуги город не забудет, —",0,386,1,0],["v","Уважь его, как ласковый сосед\".",0,387,1,0],["v","Послушают — спеши назад, откажут —",0,388,1,0],["v","Так вот тебе вторая речь: \"Гостей,",0,389,1,0],["v","Но с копьями и со щитами ждите\".",0,390,1,1],["sd","(Обращаясь в сторону, откуда пришел.)"],["v","Там, близ ручья, что «Пляской красоты»",0,390,1,0],["v","Зовет молва, в исправности стоят",0,391,1,0],["v","Мои войска — идет поверка взводов.<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,392,1,0],["v","Ну… граждане не спорили… Напротив,",0,393,1,0],["v","Желание мое предугадав,",0,393,1,0],["v","Они поход решили сами… Ба!",0,394,1,0],["v","Сюда, герольд: придется обождать…",0,395,1,0],["v","Он из Кадмеи будто…",0,396,1,0],["sd","(Герольду.)"],["v","А пожалуй,",0,396,4,0],["v","Что дело до тебя и не дойдет…",0,397,1,0],["v","Фиванцы-то меня предупредили…",0,398,1,0],["scene","Явление четвертое","s6",2,6],["sd","Те же и фиванский герольд (с внешней стороны)."],["sp","Герольд"],["v","Кто — господин страны у вас? А я",0,399,0,0],["v","Герольдом от Креонта. Над Кадмеей",0,400,0,1],["v","Он властвует с тех пор, как Полиник",0,400,0,0],["v","Убил царя и брата — Этеокла…",0,401,0,0],["v","Кому ж слова Креонта передам?",0,402,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","не сдвигаясь с места"],["v","Начало речи ложно, чужестранец:",0,403,0,0],["v","Ты ищешь здесь господ. Но город наш",0,404,0,0],["v","Монарха не имеет — он свободен,",0,405,0,0],["v","И граждане посменно каждый год",0,405,0,0],["v","Его делами правят. А богатство",0,406,0,0],["v","Для нас не власть верховная — бедняк",0,407,0,0],["v","Такой же гражданин…",0,408,0,0],["v","Имеешь слово.",1,408,0,0],["sp","Герольд"],["v","И как бы ход на шашечной доске…",0,409,0,0],["v","Одною град Фиванский волей крепок:",0,410,0,1],["v","В нем ни толпа, ни бойкий на язык",0,410,0,0],["v","Дел не решит его вития.",0,411,0,0],["v","Нами",1,411,0,0],["v","Его корысть не правит своенравно.",0,412,0,0],["v","Везет ему сегодня — он герой,",0,413,0,0],["v","А завтра — крах, и, смотришь, он обманом",0,414,0,0],["v","Уж как-то ускользает от суда.",0,415,0,0],["v","Да и вообще: ну, дело ль, чтоб невежды,",0,416,0,0],["v","Чтоб чернь кормилом правила. Досуг —",0,417,0,0],["v","Вот школа для правителя. А наспех",0,418,0,0],["v","Иль ум его созреет? Бедняку,",0,419,0,0],["v","Будь даже он и даровит, работа",0,420,0,1],["v","Тяжелая на ниве не дает",0,420,0,0],["v","Досуга о делах народа думать.",0,421,0,0],["v","А для умов повыше — прямо смерть,",0,422,0,0],["v","Коли язык, ворочаясь легко,",0,423,0,0],["v","Ничтожество иное превозносит…",0,424,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","мрачно"],["v","Герольд речист и затевает спор…<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,425,0,0],["v","Ну что ж? Когда и ты туда же, слушай!",0,426,0,0],["v","Вот — мой ответ… Сам напросился, помни!",0,427,0,0],["v","Власть одного есть худшее из зол",0,428,0,0],["v","Для города. Бессильны и законы",0,429,0,0],["v","В такой стране, где царствует тиран",0,430,0,1],["v","И где закон есть воля. Это — раз.",0,431,0,0],["v","А равенство? Совсем другое дело,",0,432,0,0],["v","Коли закон написан, если он",0,433,0,0],["v","Для всех — один; коль слабый в правом деле",0,434,0,0],["v","И богача осилит. Вот девиз",0,435,0,0],["v","Свободного народа: \"Кто советом",0,436,0,0],["v","Готов служить отчизне, говори!\"",0,437,0,0],["v","Слова несут и славу, но никто их",0,440,0,1],["v","Не требует. Вот — равенство, герольд!",0,441,0,0],["v","А далее? Где власть в руках народа,",0,442,0,0],["v","Там дети всем на радость: это — свежий",0,443,0,0],["v","Прилив народной мощи. Лишь царю",0,444,0,0],["v","Дух юности кичливой страшен. Царство",0,445,0,0],["v","Он бережет и юношей казнит,",0,446,0,0],["v","А может ли окрепнуть город, если",0,447,0,0],["v","С весны еще колосья юных сил",0,448,0,0],["v","И буйные ты сбрил в полях?",0,449,0,0],["v","А средства",1,449,0,0],["v","Зачем копить, когда не детям их",0,450,0,1],["v","Ты передашь; когда в сундук тирана",0,450,0,0],["v","Они пойдут? Невинность дочерей",0,451,0,0],["v","Оберегать зачем, коль, по желанью",0,452,0,0],["v","Верховного, они его страстям",0,453,0,0],["v","Должны служить к отцовскому позору?",0,454,0,0],["v","Уж лучше я бы умер, чем дитя б",0,455,0,0],["v","Отдать царю… Не будет ли с тебя?",0,456,0,0],["v","Скажи теперь, зачем Кадмеей послан…",0,457,0,0],["v","Ты дерзость слов оплакал бы, в тебе",0,458,0,0],["v","Когда бы Фив не чтил я. Порученье",0,459,0,0],["v","Исполнить поспеши, и с богом, гость!",0,460,0,1],["v","Креонта же вперед я поскромнее",0,460,0,0],["v","К нам вестника просил бы отряжать.",0,461,0,0],["sp","Корифей"],["v","Успех дает такую дерзость слабым,",0,462,0,0],["v","Что будто он за ними укреплен.",0,463,0,0],["sp","Герольд"],["v","Ну, к делу — так и к делу. В споре каждый",0,464,0,0],["v","Останется, конечно, при своем.",0,465,0,0],["v","Через меня фиванцы запрещают",0,466,1,0],["v","Вам принимать <span class=\"ch\" data-ch=\"adrast\">Адраста</span>. Если ж он",0,467,0,0],["v","Теперь у вас, то просим до заката",0,468,0,0],["v","Его отсюда выслать, разорвав",0,469,0,0],["v","Заклятие повязок и ветвей.<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,470,0,1],["v","А главное — все мысли о попытке",0,470,0,0],["v","Освободить тела убитых силой",0,471,0,0],["v","Придется вам оставить.",0,472,0,0],["v","И при чем",1,472,0,0],["v","Аргосцы здесь, я не пойму. Коль нас ты",0,473,0,0],["v","Послушаешь, на голубую гладь",0,473,0,0],["v","Веди ладью спокойно, ну, а если",0,474,0,0],["v","Ответишь нам отказом, бури жди",0,475,0,0],["v","Для нас и для себя и для своих",0,476,0,0],["v","Союзников. Не бойся, царь, чтоб в гневе",0,476,0,0],["v","На нашу речь и города кичась",0,477,0,0],["v","Свободою, не поспешить с коротким",0,478,0,0],["v","И резким «нет». Уверенность слепая,",0,479,0,0],["v","Вздымая дух, сгубила не один",0,480,0,1],["v","Уже народ.",0,480,0,0],["v","Когда в собранье люди",1,480,0,0],["v","Решают, быть войне или не быть,",0,481,0,0],["v","Никто себя не чает мертвым, вражьи",0,482,0,0],["v","Лишь грезятся нам трупы. Если б смерть",0,483,0,0],["v","В собраньях появлялась, так Эллада",0,484,0,0],["v","Не гибла бы, быть может, как теперь,",0,485,0,0],["v","В безумной жажде браней.",0,485,0,0],["v","Всякий знает,",1,485,0,0],["v","Что хорошо, что дурно. Кто б из двух",0,486,0,0],["v","Вещей не выбрал лучшей? Отчего же",0,487,0,0],["v","Упрямо в толк никак мы не возьмем,",0,488,0,0],["v","Насколько мир войны прекрасней, музам",0,489,0,0],["v","Любезный мир и ненавистный ада",0,490,0,1],["v","Исчадиям; и златом и детьми",0,490,0,0],["v","Богатый мир. А мы заводим войны,",0,491,0,0],["v","Порабощаем слабого, мужи —",0,492,0,0],["v","Мужей и города — друг друга.",0,493,0,0],["v","Ты за мужей, восставших на богов,",0,493,1,0],["v","Вступаешься. Их погубила дерзость.",0,494,0,0],["v","А ты тела их хочешь хоронить.",0,495,0,0],["v","Да разве ж не поклялся Капаней,<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,496,0,0],["v","К стене приставив сходни, город рушить,",0,496,0,0],["v","Хотя бы бог того не допускал?..",0,497,0,0],["v","Что ж? Скажешь: смерть, его испепелив",0,498,0,0],["v","Перуном, не была достойной карой",0,499,0,0],["v","Для дерзкого? А не сама ль земля<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,500,0,1],["v","Разверзлась, чтоб принять в свои глубины",0,500,0,0],["v","Гадателя и с лошадьми? И разве",0,501,0,0],["v","Другие с раскроенной головой",0,502,0,0],["v","Под стенами не пали? Если лучшим",0,503,0,0],["v","Себя судьей не мнишь ты, чем Кронид,",0,503,0,0],["v","Признай, что злых он покарал по правде.",0,504,0,0],["v","Для мудрого милей, чем дети, нет,",0,505,1,0],["v","Но тотчас вслед — родители, отчизна,",0,506,0,0],["v","И должен он ее приумножать,",0,506,0,0],["v","А не крушить. Опоры нет ни в дерзком",0,507,0,0],["v","Вожде, ни в моряке. Они должны",0,508,0,0],["v","И в бурю быть спокойны. Осторожность —",0,509,0,0],["v","Нет мужества надежней меж людей.",0,510,0,1],["sp","Корифей"],["v","Их покарал всевышний, и довольно…",0,511,0,0],["v","Лишь дерзостны глумления твои.",0,512,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","О, низость!.. О, позор!",0,513,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","останавливая его жестом"],["v","Ни слова, царь!",1,513,0,0],["v","Не выступай вперед с твоим ответом.",0,514,0,0],["v","Герольд пришел ко мне, а не к тебе,",0,515,0,0],["v","И отвечать ему — уж наше дело.",0,516,0,0],["v","Вот мой ответ на первые слова",0,517,0,0],["v","Герольдовы. Не знал я до сегодня,",0,518,0,0],["v","Что мне Креонт — начальство иль что нас",0,519,0,0],["v","Настолько он сильнее, чтоб Афинам",0,520,0,1],["v","Приказывать… Нам ждать ли приказаний?",0,520,0,0],["v","Да прежде пусть на эту высоту",0,521,0,0],["v","Морские волны хлынут…",0,522,0,0],["v","Я войны",1,522,0,0],["v","Не разжигал, в походе Семерых",0,522,0,0],["v","На Фивы не причинен. Погребенья",0,523,0,0],["v","Оставшимся на поле битвы я",0,524,0,0],["v","Хочу, и только. До Кадмеи ж это",0,524,0,0],["v","Едва ли и относится: ее",0,525,0,0],["v","Кровавой мы не наполняем распрей.",0,526,0,0],["v","Похороните мертвых, потому что",0,526,0,0],["v","Таков закон Эллады. Где ж ты тут",0,527,0,0],["v","Нашел несправедливость? Аргос был,",0,528,0,0],["v","По-твоему, неправ. Ну что ж? Он землю",0,528,0,0],["v","Покрыл за то телами сыновей.",0,529,0,0],["v","Вам, отразившим, — слава, им — позор.",0,530,0,1],["v","И, значит, — квит. Но дайте ж мир усопшим,",0,530,0,0],["v","Пусть их земля засыплет. И на свет",0,531,0,0],["v","Откуда что явилось, пусть вернется —",0,532,0,0],["v","Дыхание в эфир, а тело в землю.<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,532,0,0],["v","Здесь человек — жилец. Земля его",0,533,0,0],["v","Вскормила оболочку, и не людям —",0,534,0,0],["v","Земле она принадлежит. О чем же",0,535,0,0],["v","Тут толковать? Иль, тел не хороня,",0,535,0,0],["v","По-твоему, над Аргосом одним",0,536,0,0],["v","Злотворствуешь? Отнюдь. Вы всю Элладу",0,537,0,0],["v","Затронули, лишая мертвецов",0,537,0,0],["v","Могилы их. Ты только возведи",0,538,0,0],["v","В закон явленье это — и сильнейших",0,539,0,0],["v","Ты обратишь в трусливых. Чудеса!",0,540,0,1],["v","Живому, мне грозить вы не страшитесь,",0,541,0,0],["v","А трусите, чтоб мертвого земля",0,542,0,0],["v","Засыпала. Да что ж произойти",0,543,0,0],["v","Тогда должно? С землей сровняют Фивы",0,544,0,0],["v","Покойники зарытые? Детей",0,545,0,0],["v","Там, под землей, родят для наказанья",0,546,0,0],["v","Фиванцев, что ль? Все это — трата слов,",0,547,0,0],["v","И глупая. Поймите же, слепые,",0,548,0,0],["v","Бессилие людей. Не на борьбу ль",0,549,0,0],["v","Похожа жизнь? Сегодня — я, ты — завтра,",0,550,0,1],["v","Он послезавтра сверху. Божеству",0,550,0,0],["v","Тому всегда раздолье. Плохо людям,",0,551,0,0],["v","Они с дарами к богу — выручай.",0,552,0,0],["v","А в счастии его возносят имя,",0,552,0,0],["v","Чтоб сохранить удачу им и ветра",0,553,0,0],["v","Не изменять попутного.",0,554,0,0],["v","А кто",1,554,0,0],["v","Уразумел, что это так, обиды",0,555,0,0],["v","Ничтожные переноси с терпеньем",0,555,0,0],["v","И бойся на страну свою навлечь",0,556,0,0],["v","Несчастие, нарушив справедливость.",0,557,0,0],["v","Итак, к чему ж пришли мы? Дайте нам",0,557,0,0],["v","Земле предать убитых, делом божьим",0,558,0,0],["v","Заняться не мешайте. А не то",0,559,0,0],["v","Я силою их вызволю. Не скажут,",0,560,0,1],["v","Что наш закон божественный и древний",0,561,0,0],["v","Нарушен был в Афинах и при мне.",0,562,0,0],["sp","Корифей"],["v","Но этого ль бояться? Пламя Правды<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,563,0,0],["v","Хранящего не трогает молва.",0,564,0,0],["sp","Герольд"],["v","Позволишь ли на это только слово…",0,565,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Ну, говори… Ты любишь говорить.",0,566,0,0],["sp","Герольд"],["v","Не получить тебе от нас аргосцев.",0,567,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","И мой ответ послушай, если так.",0,568,0,0],["sp","Герольд"],["v","Приходится послушать. Я сговорчив.",0,570,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Я схороню тела. Я унесу",0,570,0,0],["v","Их с берегов Асопа. Понимаешь?<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,571,0,0],["sp","Герольд"],["v","Отважившись на крепкий бой сперва.",0,572,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Не первый раз, заметь себе, отважусь…",0,573,0,0],["sp","Герольд"],["v","Или таким отец тебя родил,",0,574,0,0],["v","Что одного на всех <span class=\"ch\" data-ch=\"tesey\">Тесея</span> хватит?",0,575,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Злодеев, да. Мы добрых не казним.",0,575,0,0],["sp","Герольд"],["v","Покоя нет от вас, и царь и город!",0,576,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Коль без борьбы и счастья не добыть.",0,577,0,0],["sp","Герольд"],["v","Что ж! Испытай, покойны ль нивы Спартов?<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,578,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","От змея ли пойдет воинский пыл?",0,579,0,0],["sp","Герольд"],["v","Испробуешь. Покуда ж, видно, молод.",0,580,0,1],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Кичливостью своею, все равно,",0,580,0,0],["v","Ты не рассердишь их. Но не пора ль",0,581,0,0],["v","С запасом слов пустых и восвояси?",0,582,0,0],["v","Мы ни к чему прийти не можем.",0,583,0,0],["v","Герольд уходит в чужую сторону.",0,584,0,0],["scene","Явление пятое","s7",2,7],["sd","Те же, без герольда."],["v","Вы ж,",0,585,4,0],["v","Гоплиты, вы, владельцы колесниц,",0,585,0,0],["v","Идем в поход! И конные за нами!",0,586,0,0],["v","Пусть пеною покроется узда",0,587,0,0],["v","Упрямого коня. На землю Кадма",0,588,0,0],["v","Я вас веду, солдаты, к семивратной",0,589,0,0],["v","Его твердыне древней.",0,590,0,1],["sd","(<span class=\"ch\" data-ch=\"adrast\">Адрасту</span>.)"],["v","Ты ж, аргосец,",0,590,4,0],["v","Останься здесь. Мешать мы не хотим",0,591,0,0],["v","Твоей удачи с нашей. С славным войском",0,592,0,0],["v","И не бесславен сам иду теперь",0,593,0,0],["v","На собственное счастье.",0,593,0,0],["v","Кто за правду",1,593,0,0],["v","Стоит, тому одно лишь нужно — с ним",0,594,0,0],["v","Бессмертные чтоб были. Бог да Правда",0,595,0,0],["v","Одни дают победу. А без бога",0,596,0,0],["v","И мужество не выручит людей.",0,596,0,0],["sd","(Идет в ту сторону, куда ушел герольд, со свитой и людьми.)"],["scene","Второй музыкальный антракт","s8",2,8],["sp","Первое полухорие"],["str","Строфа I"],["v","Матери, горем убитые,",0,597,0,0],["v","Горьких вождей! Мое сердце,",0,598,0,0],["v","Сердце сжимается страхом.",0,599,0,0],["sp","Второе полухорие"],["v","Что ж голос страха этот означает?",0,600,0,1],["sp","Первое полухорие"],["v","Что выйдет из Тесеева похода?",0,600,0,0],["sp","Второе полухорие"],["v","Как думаешь ты? бой иль соглашенье?",0,601,0,0],["sp","Первое полухорие"],["v","Может быть, к лучшему все.",0,602,0,0],["v","Если же грудью на грудь",0,603,0,0],["v","Яро сразятся враги, —",0,604,0,0],["v","Горе мне, горе! За это",0,605,0,0],["v","Я ведь отвечу:",0,605,1,0],["v","Брань не я ли зажгла!?",0,606,0,0],["sp","Второе полухорие"],["str","Антистрофа I"],["v","Горд он сегодня удачею,",0,607,0,0],["v","Завтра он с жребием черным…",0,608,0,0],["v","Это живит мою бодрость.",0,609,0,0],["sp","Первое полухорие"],["v","Ты думаешь, что боги справедливы?",0,610,0,1],["sp","Второе полухорие"],["v","А кто ж другой меж нами делит счастье?",0,610,0,0],["sp","Первое полухорие"],["v","Но их дележ, увы, неравномерен.",0,611,0,0],["sp","Второе полухорие"],["v","Ужас слепит вас опять.",0,612,0,0],["v","Слушайте: кровью за кровь —",0,613,0,0],["v","Вот наш ответ, наш закон.",0,614,0,0],["v","Боги венчают страданье",0,615,0,0],["v","Отдохновеньем…",0,615,1,0],["v","Все концы у богов.",0,616,0,0],["sp","Первое полухорие"],["str","Строфа II"],["v","Если б отсюда,",0,617,0,0],["v","От Элевсинских вод,",0,618,0,0],["v","В Фивы кто снес меня!",0,619,0,0],["sp","Второе полухорие"],["v","Крыльев у бога себе проси!",0,620,0,1],["v","Вот окрылись,",0,620,1,0],["v","Живо узнаешь,",0,621,1,0],["v","Что там у них теперь…",0,622,0,0],["sp","Первое полухорие"],["v","Дело-то спорится ль?",0,623,0,0],["v","Крепкий герой у них,",0,624,0,0],["v","Что раздобыл <span class=\"ch\" data-ch=\"tesey\">Тесей</span>!",0,625,0,0],["sp","Второе полухорие"],["str","Антистрофа II"],["v","Будем молиться…",0,626,0,0],["v","Мало ль молились мы,",0,627,0,0],["v","Да не дрожащие?!",0,628,0,0],["sp","Первое полухорие"],["v","Аргоса корень! О Зевс-отец!",0,629,0,0],["v","Кто ж, как не ты,",0,630,1,1],["v","Вышний, заступишь",0,630,1,0],["v","Силу Тесееву?",0,631,0,0],["sp","Второе полухорие"],["v","Вызволи Аргоса",0,632,0,0],["v","Цвет от позора, бог!",0,633,0,0],["v","Дай схоронить детей!",0,633,0,0],["act","Действие третье","a3","III"],["scene","Явление шестое","s9",3,9],["sd","Хор, <span class=\"ch\" data-ch=\"adrast\">Адраст</span> и аргосский вестник (с внешней стороны)."],["sp","Вестник"],["v","О женщины! Я радостный посол.",0,634,0,0],["v","Сам вырвался на волю я (захвачен",0,635,0,0],["v","В сражении у вод Диркейских, в плене",0,636,0,0],["v","Я был, что семь царей покойных дали",0,636,0,0],["v","Фиванскому народу). Победил",0,637,0,0],["v","Афинский царь. А об себе прибавлю",0,638,0,0],["v","Без дальних слов, что царь мой Капаней",0,639,0,0],["v","Был Зевсовым испепелен перуном.",0,640,0,1],["sp","Корифей"],["v","О друг! Твоей удаче рады мы",0,640,0,0],["v","И вести о <span class=\"ch\" data-ch=\"tesey\">Тесее</span>. Но спокойной",0,641,0,0],["v","Могла бы быть я, только услыхав,",0,642,0,0],["v","Что воины Афин благополучны.",0,643,0,0],["sp","Вестник"],["v","И ты об этом слышишь. Пусть бы так",0,644,0,0],["v","Под Фивами аргосцы и с <span class=\"ch\" data-ch=\"adrast\">Адрастом</span>",0,645,0,0],["v","Благополучны были, как они.",0,646,0,0],["sp","Корифей"],["v","Но как же сын Эгеев и войска",0,647,0,0],["v","Крониду тот трофей воздвигли, вестник?",0,648,0,0],["v","Обрадуй нас, глашатай слов златых.",0,649,0,0],["sp","Вестник"],["v","Блестящие и чуждые обмана",0,650,0,1],["v","Лучи светила Гелия в поля",0,650,0,0],["v","Кадмеи ударяли. Я смотрел",0,651,0,0],["v","С высокой башни близ ворот Электры.",0,652,0,0],["v","Афиняне на три передо мной",0,653,0,0],["v","Отряда по оружию делились.",0,654,0,0],["v","До самого Исмена, говорят,<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,655,0,0],["v","Гоплиты простирались, края древней",0,655,0,0],["v","Кекропии питомцы, — и <span class=\"ch\" data-ch=\"tesey\">Тесей</span>",0,656,0,0],["v","В их голове на правом фланге стал.",0,657,0,0],["v","На левом же паралии, и их<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,658,0,0],["v","Не менее числом гоплитов было.",0,659,0,0],["v","Насупротив Ареева ручья",0,660,0,1],["v","Тянулись боевые колесницы,<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,660,0,0],["v","И, наконец, у гроба Амфиона",0,661,0,0],["v","Стояла кавалерия и строй",0,662,0,0],["v","Афинский замыкала. Возле стен<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,663,0,0],["v","Позицию фиванцы занимали,",0,663,0,0],["v","Загородив свой страшный приз — тела;",0,664,0,0],["v","А конница и колесницы их",0,665,0,0],["v","Пред вражьими как раз же приходились.",0,666,0,0],["v","И вот приказ герольда прозвучал —",0,666,0,0],["v","То ясные слова <span class=\"ch\" data-ch=\"tesey\">Тесея</span> были:",0,667,0,0],["v","\"О воины, замолкните! И вы",0,668,0,0],["v","Прислушайтесь, фиванские отряды!",0,669,0,0],["v","Мы за телами павших здесь, чтоб их",0,670,0,1],["v","Похоронить — мы защищаем право,",0,670,0,0],["v","Всем эллинам священное, — ничуть",0,671,0,0],["v","Мы не хотим убийства\".",0,672,0,0],["v","Но призыву",1,672,0,0],["v","Не внял Креонт. Упорно и в молчанье",0,673,0,0],["v","Его войска хранили грозный вид.",0,674,0,0],["v","Открылся бой с военных колесниц…",0,675,0,0],["v","Вот смялися, поправши строй, вот копья",0,676,0,0],["v","Уж, кажется, скреститься метят. Первый",0,677,0,0],["v","Разбег, и вспять ворочают коней",0,678,0,0],["v","Возницы, чтоб усилить нападенье.",0,679,0,0],["v","То конницы афинской увидал",0,680,0,1],["v","Искусный вождь Форбад, и он дает",0,681,0,0],["v","Немедля знак своим. И вот с Форбадом",0,682,0,0],["v","Сшибаются кавалеристы Фив.",0,683,0,0],["v","Я близко был от места битвы, мог бы",0,684,0,0],["v","Я перечесть во всей их полноте",0,685,0,0],["v","Ужасные картины, но с чего,",0,686,0,0],["v","Скажи, начать? С столбов ли пыли черной,",0,687,0,0],["v","Что к небесам вздымалась? С колесниц",0,688,0,0],["v","Мятущихся или людей, что, кровью",0,689,0,0],["v","Залитые, влачились на вожжах,",0,690,0,1],["v","Запутавшись в ремни своих упряжек?",0,691,0,0],["v","Один упал, другой через него,",0,692,0,0],["v","Как акробат, слетает с колесницы,",0,693,0,0],["v","И оба — бездыханны. Но Креонт,",0,694,0,0],["v","Заметивши, что всадников успехи",0,695,0,0],["v","Становятся для строя все грозней,",0,696,0,0],["v","Хватается за щит. Вот он в атаку",0,697,0,0],["v","Скомандовал. Минуты и <span class=\"ch\" data-ch=\"tesey\">Тесей</span>",0,698,0,0],["v","Не потерял — и он открыл движенье,",0,699,0,0],["v","Доспехами блистая. Строй на строй,",0,700,0,1],["v","Бегут, сшибаются, резня и рукопашный",0,700,0,0],["v","Повсюду бой. Кричали: \"Бейте их!",0,701,0,0],["v","Тесните вон афинян!\" Да, боец",0,702,0,0],["v","Не слабый из зубов дракона вырос,",0,703,0,0],["v","Фиванский люд. И вот на левом фланге",0,704,0,0],["v","Мы подались. Но правое крыло",0,705,0,0],["v","Кадмейское бежало. Колебались",0,706,0,0],["v","Весы, качались ровно. Тут царю",0,707,0,0],["v","Афинскому хвала! Своим успехом",0,708,0,0],["v","Не опьянен, он к дрогнувшим спешит, —",0,709,0,0],["v","И потряслась земля от клича: \"Дети!",0,710,0,1],["v","Коль вы не устоите, то Афин",0,710,0,0],["v","Исчезнет имя самое под игом",0,711,0,0],["v","Драконова рожденья\". Эта речь",0,712,0,0],["v","Вздымает дух кранайцев. Сам хватает<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,713,0,0],["v","Он палицу, что некогда себе",0,714,0,0],["v","Из Эпидавра вывез. Страшны были",0,715,0,0],["v","Тяжелые размахи, и голов",0,716,0,0],["v","Клонилось бремя с плеч, и, как колосья,",0,717,0,0],["v","Летели шлемы спартов… Наконец",0,718,0,0],["v","Враги сдались. Тут в радости я начал",0,719,0,0],["v","В ладони бить, плясать и петь. Они ж",0,720,0,1],["v","К воротам потянулись. Вой и стоны",0,720,0,0],["v","По городу и молодых и старых",0,721,0,0],["v","Носились, и, сбегаясь, наполняли",0,722,0,0],["v","Они смятеньем храмы. Город был",0,722,0,0],["v","Афинянам открыт, но сам <span class=\"ch\" data-ch=\"tesey\">Тесей</span>",0,723,0,0],["v","Дружины удержал: \"Не рушить Фивы,",0,724,0,0],["v","А отобрать убитых мы пришли.",0,725,0,0],["v","Ведь так и объявил я\". Выбор должен",0,725,0,0],["v","Таких вождей давать, чтобы они,",0,726,0,0],["v","В опасности тверды, для дерзкой черни",0,727,0,0],["v","Узду найти умели. Эта чернь",0,727,0,0],["v","Хмелеет от удачи и готова,",0,728,0,0],["v","За лестницу цепляясь, о верхах",0,729,0,0],["v","Мечтать, успех свой скромный презирая.",0,730,0,1],["sp","Корифей"],["v","Желанный день! Я смела ль ожидать,",0,730,0,0],["v","Что ты придешь? Нет, бог, и точно, есть.",0,731,0,0],["v","Враг заплатил — и сердцу будто легче.",0,732,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","О вышний бог! А говорят еще,",0,733,0,0],["v","Что человек разумен. Где ж он, разум?",0,734,0,0],["v","Да разве мы не у тебя в руках,",0,735,0,0],["v","Не делаем все, что Кронид захочет?",0,736,0,0],["v","Наш Аргос, он еще ли был не крепок?",0,737,0,0],["v","Самих ли не так было мало, или",0,738,0,0],["v","Рук молодых нам не хватало? Царь",0,739,0,0],["v","Фиванский был умерен — но ему",0,740,0,1],["v","Мы не сдалися в малом — и погибли…",0,740,0,0],["v","Фиванцы же, сначала победив,",0,741,0,0],["v","Как нищий, вдруг разбогатевший, стали",0,742,0,0],["v","Высокомерны в счастии, и вот",0,743,0,0],["v","И их теперь сгубило ослепленье.",0,744,0,0],["v","Какой пустой задор! Не уступить",0,745,0,0],["v","Добром и ждать, что нож приставят к горлу.",0,746,0,0],["v","А города? Могли бы примирить",0,747,0,0],["v","Переговором граждан — нет: убийство",0,748,0,0],["v","Меж них дела вершит. А речь на что ж?",0,749,0,0],["v","Однако бросим это. Сам-то спасся",0,750,0,1],["v","Ты как, скажи?.. А там еще спрошу…",0,751,0,0],["sp","Вестник"],["v","А под шумок — пока они теснились,",0,752,0,0],["v","Ища спасенья в Фивах, — ускользнул…",0,753,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Но мертвые, добыча ваша, с вами ль?",0,754,0,0],["sp","Вестник"],["v","Да, семерых вождей мы принесли.",0,755,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Одних вождей? А вся дружина мертвых?",0,756,0,0],["sp","Вестник"],["v","Могила их — лесистый Киферон.",0,757,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Но кто ж зарыл в лесу: они ли, мы ли?",0,758,0,0],["sp","Вестник"],["v","Нет, царь <span class=\"ch\" data-ch=\"tesey\">Тесей</span> близ Элевферских скал.<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,759,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Где ж обогнал ты незарытых, вестник?",0,760,0,1],["sp","Вестник"],["v","А в двух шагах. Усердье ведь что бич.",0,760,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Рабам-то, чай, нести их было трудно?",0,761,0,0],["sd","Вестний"],["v","Без помощи рабов мы обошлись.",0,762,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Как? Сам <span class=\"ch\" data-ch=\"tesey\">Тесей</span> им оказал вниманье?<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,763,0,0],["sp","Вестник"],["v","Со стороны подумаешь — друзья.",0,764,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","И обмывал он сам тела несчастных?",0,765,0,0],["sp","Вестник"],["v","Постели стлал и покрывал их сам.",0,766,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Та не легка любовная услуга.",0,767,0,0],["sp","Вестник"],["v","Послужим мы — послужит кто и нам.",0,768,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Зачем и я не труп и не меж ними?",0,769,0,0],["sp","Вестник"],["v","Без жалоб, царь. Из материнских глаз",0,770,0,1],["v","Ты новые зовешь не в пору слезы.",0,770,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Не мне учить их этому, посол.",0,771,0,0],["v","Но что же я? Скорей туда, навстречу!",0,772,0,0],["v","С воздетыми руками, с током слез",0,773,0,0],["v","И гимнами надгробными приму я",0,773,0,0],["v","Соратников почивших. Ведь из них",0,774,0,0],["v","Один я уцелел, чтоб их оплакать.",0,775,0,0],["v","Именье ль ты, богатство ль потерял —",0,776,0,0],["v","Вернуться может все. Лишь человека",0,776,0,0],["v","Утратив, ты поймешь, что это значит!",0,777,0,0],["sd","(Уходит направо с вестником и эпигонами.)"],["scene","Третий музыкальный антракт","s10",3,10],["sp","Хор"],["str","Строфа I"],["v","И радость и мука!",0,778,2,0],["v","Афинам-то, конечно, только слава!",0,779,0,0],["v","И два венца вождю!",0,780,2,1],["v","А я детей тела укрыть",0,781,2,0],["v","Дрожу. Но час придет нежданный этот,",0,782,0,0],["v","И зрелище прекрасным назову,",0,783,0,0],["v","Насытив сердце плачем…",0,784,2,0],["str","Антистрофа I"],["v","О пусть бы безбрачной",0,785,2,0],["v","Оставило меня седое время,",0,786,0,0],["v","Отец крылатых дней!",0,787,2,0],["v","На что ж детей рождала я?",0,790,2,1],["v","Я думала — не выйти замуж горько,",0,791,0,0],["v","А горе-то сегодня в первый раз",0,792,0,0],["v","Пойму, теряя сына.",0,793,2,0],["sp","Корифей"],["v","Уж шествие печальное открылось…",0,794,0,0],["v","О, горе нам! Коль надо умереть,",0,795,2,0],["v","Чтоб быть с детьми…",0,796,2,0],["v","Стрела, зачем ты медлишь?<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,797,2,0],["act","Действие четвертое","a4","IV"],["scene","Явление седьмое","s11",4,11],["sd","В орхестре торжественная процессия. Ее открывает <span class=\"ch\" data-ch=\"adrast\">Адраст</span> и отроки. Затем следует семеро покрытых носилок, из коих двое без мертвых. Шествие замыкает <span class=\"ch\" data-ch=\"tesey\">Тесей</span> со свитой."],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["str","Строфа II"],["v","Матери, стонами,",0,798,0,0],["v","Стоном на стоны мне",0,799,0,0],["v","Вы ль не ответите!",0,800,0,1],["v","Хору",0,800,4,0],["v","О дети, из уст родимых",0,801,0,0],["v","Горько привета слово,",0,802,0,0],["v","Горько звучит над мертвыми!",0,802,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","О, увы!",0,803,0,0],["sp","Хор"],["v","Увы мне, удар попал!",0,804,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Ай! Ай!",0,805,0,0],["sp","Хор"],["v","Железо пожрало их.",0,805,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","О, пострадали мы…",0,806,0,0],["sp","Хор"],["v","Сил нет… Ой, смерть моя…",0,807,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Аргос мой! Я ль не женат?",0,807,0,0],["v","Аргос! О славный Аргос!",0,808,0,0],["sp","Хор"],["v","Он смотрит и на нас, тот Аргос,",0,809,0,0],["v","Бедных, безнадежных…",0,810,0,1],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["dir","обращаясь к остановившимся носильщикам"],["sd","Антистрофа II Дайте ж сюда тела!"],["sd","Тела по знаку <span class=\"ch\" data-ch=\"adrast\">Адраста</span> ставят перед матерями; они не сразу, однако, подходят к ним; слезы продолжаются."],["v","Стойко отбитые —<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,810,0,0],["v","Не поношение ль",0,811,0,0],["v","Смерть их была, увы!",0,812,0,0],["sp","Хор"],["sd","Матери страшным, сплошным движением бросаются на носилки. Служанки удерживают их, по приказанию мужчин (с жестами отчаяния)."],["v","О, дайте обнять ребенка!",0,813,0,0],["v","К сыну прижаться грудью",0,814,0,0],["v","Дайте его носившей!",0,815,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Будет вам…",0,816,0,0],["sp","Хор"],["v","Я мукой купила их…",0,817,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","О… о…",0,818,0,0],["sp","Хор"],["v","Взываешь ты к матери?",0,819,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Стонам внемли моим.",0,820,0,1],["sp","Хор"],["v","Мука связала нас.",0,820,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Пусть между трупов ратных",0,821,0,0],["v","В поле и я был мертвым!",0,822,0,0],["sp","Хор"],["v","О, если б никогда на ложе",0,823,0,0],["v","Не обняла я мужа!",0,823,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["str","Эпод"],["v","Вот оно, море бедствий!",0,824,0,0],["v","Матери, плачете, плачьте!",0,825,0,0],["sp","Хор"],["v","По щеке моей струится",0,826,0,0],["v","Бороздами кровь, и пепел",0,826,0,0],["v","Кроет волосы седые.",0,827,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Горе мне, горе, о горе!",0,828,0,0],["v","Пусть бы земля разверзлась!",0,829,0,0],["v","Пусть бы сорвалась буря!",0,830,0,1],["v","Пусть от стрелы небесной",0,830,0,0],["v","Череп бы мой распался!",0,831,0,0],["sp","Хор"],["dir","в мрачном экстазе к <span class=\"ch\" data-ch=\"adrast\">Адрасту</span>"],["v","Брак ты справил несчастливый,",0,832,0,0],["v","И проклятье было в этом",0,832,0,0],["v","Предвещанье Аполлона.",0,833,0,0],["v","К нам из Фив",0,834,0,0],["v","Перешел детоубийца,",0,835,0,0],["v","Черный демон перешел",0,835,0,0],["v","Из Эдипова чертога…",0,836,0,0],["v","Плач мало-помалу стихает. Входит <span class=\"ch\" data-ch=\"tesey\">Тесей</span>.",0,837,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","к <span class=\"ch\" data-ch=\"adrast\">Адрасту</span>"],["v","Уже когда перед лицом дружин",0,837,0,0],["v","Оплакивал ты мертвых, мой вопрос",0,838,0,0],["v","Сложился, но ему я воли не дал…",0,839,0,0],["v","Скажи теперь, Адраст, мне, кто они,",0,840,0,1],["v","Те смельчаки, откуда род геройский",0,841,0,0],["v","Они ведут? Наставь моих бойцов",0,842,0,0],["v","Ты, сведущий, афинян юных этих.",0,843,0,0],["v","Воочию мы оценили их",0,844,0,0],["v","Безумную отвагу. Фивы штурмом",0,845,0,0],["v","Дерзали брать… Оставлю в стороне",0,846,0,0],["v","Смешное любопытство: как враги",0,847,0,0],["v","В сражении распределялись, чьим",0,848,0,0],["v","Был именно копьем и кто заколот.",0,849,0,0],["v","Фантазии! Ну кто, спрошу, видал",0,850,0,1],["v","Сквозь натиск боевой, где копья тучей",0,850,0,0],["v","В лицо ему мелькали, как сосед",0,851,0,0],["v","Его погиб. Расспрашивать об этом",0,852,0,0],["v","Не собираюсь я, и за ответ",0,853,0,0],["v","Могли бы вы ручаться, что он точен,",0,854,0,0],["v","Я все ж бы не поверил. Если враг",0,855,0,0],["v","Перед тобой — и важное просмотришь.",0,856,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","О, только слушай! Я же счастлив, царь,",0,857,1,0],["v","Хвалу друзьям воздать во имя Правды",0,858,1,0],["v","И Истины. И твой прекрасен дар.",0,859,1,0],["sd","(Указывает на первые закрытые носилки.)"],["v","Пронизанный Кронидовой стрелою,",0,860,1,1],["v","Там Капаней. Чего он не имел?",0,861,1,0],["v","Но золотом своим не величался",0,862,1,0],["v","И бедняка скромнее жил. Стола",0,863,1,0],["v","Обилье презирал он, не в пирах",0,864,1,0],["v","Отличия искал. \"Иль сытым быть, —",0,865,1,0],["v","Он говорил, — так мудрено?\" Надежный",0,866,1,0],["v","В глаза ли друг иль за глаза он был.",0,867,1,0],["v","Друзья такие редки. Сердце он",0,868,1,0],["v","Открытое имел. И улыбался",0,869,1,0],["v","Всем ласково. А чванства ни рабы,",0,870,1,1],["v","Ни граждане в покойном не видали.",0,870,1,0],["sd","(Подходя ко вторым.)"],["v","Вот Этеокла прах. И в нем блистал<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,871,1,0],["v","Алмаз, но новой гранью. Этот молод",0,872,1,0],["v","И беден был. Но никогда почет",0,873,1,0],["v","Не обошел его. Героем славным Аргос",0,874,1,0],["v","Наш дорожил. И у друзей легко",0,875,1,0],["v","Он находил поддержку, хоть свободы",0,875,1,0],["v","Решений им своих не продавал.",0,876,1,0],["v","Он быть врагом умел вождей фальшивых,",0,877,1,0],["v","Не самого народа. Да за что ж",0,878,1,0],["v","Казнить народ? Как будто он виновен,",0,879,1,0],["v","Коль не туда советники ведут!",0,880,1,1],["sd","(У третьего одра.)"],["v","Вот третий вождь — и новое отличье:",0,880,1,0],["v","Гиппомедон был отроком еще,",0,881,1,0],["v","Когда решил он гордо, что ни Музы,",0,882,1,0],["v","Ни нега не возьмут его — в полях",0,883,1,0],["v","Он закалял себя на ловах, диких",0,884,1,0],["v","Смиряя лошадей или тугой",0,885,1,0],["v","Сгибая лук. Всего себя отчизне,",0,885,1,0],["v","Всю силу он берег.",0,886,1,0],["sd","(К четвертому.)"],["v","А здесь почил",0,887,4,0],["v","Парфенопей, рожденье Аталанты.",0,888,1,0],["v","Почти дитя, а до чего красив!",0,889,1,0],["v","Аркадия была его отчизной,",0,890,1,1],["v","Но в Аргосе он вырос, как метэк.",0,890,1,0],["v","Парфенопей был скромен: он аргосцам",0,891,1,0],["v","Не докучал — зато и между нас<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,892,1,0],["v","Враждебных лиц не видел. Спорщик не был,",0,893,1,0],["v","Вот — главное. Чужой ли, свой ли нам,",0,894,1,0],["v","Но спорщики всегда невыносимы.",0,895,1,0],["v","В челе других не хуже дрался он",0,895,1,0],["v","Природного аргосца, утешаясь",0,896,1,0],["v","Удачей наших граждан и скорбя",0,897,1,0],["v","За их урон. Его краса желанья",0,898,1,0],["v","Рождала и соблазны, но стоял",0,899,1,0],["v","На страже он, чтоб не поддаться лести.",0,900,1,1],["sd","(Подходя к пятому ложу.)"],["v","Вот и Тидей. Великой похвале",0,901,1,0],["v","Обилья слов не надо. Он словами",0,902,1,0],["v","И не блистал. С копьем же был софист,",0,903,1,0],["v","Для воинов неопытных опасный.",0,904,1,0],["sd","(<span class=\"ch\" data-ch=\"tesey\">Тесею</span>.)"],["v","Мои слова усвоив, не дивись,",0,905,1,0],["v","Что умереть отважились такие,",0,910,1,1],["v","Штурмуя кремль. И чувству чести, царь,",0,910,1,0],["v","Потребно воспитанье. Если сердце",0,911,1,0],["v","Ты закалил отвагой, стыд не даст",0,912,1,0],["v","Тебе бежать. И доблести ведь учат,",0,913,1,0],["v","Как прочему: как говорить и слушать.",0,914,1,0],["v","Природа нам познаний не дает,",0,915,1,0],["v","До старости зато уроки целы.",0,915,1,0],["v","Итак вот первый долг —",0,916,1,0],["sd","(указывая на отроков)"],["v","учить детей.",0,917,4,0],["sp","Хор"],["dir","не подходя к носилкам"],["v","О дитя! Не на радость тебя",0,918,0,0],["v","Под сердцем носила, кормила",0,919,0,0],["v","Я, в муках горьких тебя родив.",0,920,0,1],["v","Та мука моя у Аида,",0,921,0,0],["v","А мне, горемычной, к закату",0,922,0,0],["v","Опоры и той не осталось —",0,923,0,0],["v","Рожденного трудно кормильца.",0,924,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","указывая на пустые носилки"],["v","Меж павшими почтен Амфиарай:",0,925,0,0],["v","Живым его и с колесницей боги",0,926,0,0],["v","В земные недра приняли. Мой долг",0,927,0,0],["v","Воздать хвалу открыто Полинику.",0,928,0,0],["v","Он был мой гость, покуда Фив еще",0,930,0,1],["v","Не покидал для Аргоса, себя",0,930,0,0],["v","Печальному изгнанью обрекая…",0,931,0,0],["v","А знаешь, что я сделаю теперь?",0,932,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Одно — тебе повиноваться — знаю.",0,933,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Пусть Капаней — его отметил Зевс…",0,934,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","…Горит один, бессмертных достоянье.<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,935,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Ты угадал. Других — в один костер.",0,936,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Но где же гроб отдельный ты наметишь?",0,937,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","У храма здесь столбы велю я врыть.",0,938,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Для рабских рук, конечно, то работа.",0,939,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","подходя к одним носилкам"],["v","А мы других схороним. Поднимай!",0,940,0,1],["v","Воины присоединяются к нему.",0,933,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["dir","хору"],["v","Ну, матери, идите попрощайтесь.",0,925,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["dir","останавливая с плачем идущих к телам женщин, <span class=\"ch\" data-ch=\"adrast\">Адрасту</span>"],["v","Оставь, Адраст! Не дело говоришь.",0,918,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Как? Матерям нельзя детей касаться?",0,910,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Не вынесут ужасных перемен.",0,903,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Сукровица и язвы, точно, страшны.",0,895,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Иль мало им уж пережитых мук?",0,888,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Сдаюсь, Тесей! Крепитесь же, старухи!",0,880,0,0],["v","Совет хорош Останки мы сожжем",0,873,0,0],["v","И отдадим вам пепел. Вы детей<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,865,0,0],["v","Обнимете, но в урнах…",0,858,0,0],["v","Люди, люди!",1,858,0,0],["v","Хватаются за копья, тяжких ран",0,850,0,1],["v","Ослеплены угрозой…",0,851,0,0],["v","Лучше каждый",1,851,0,0],["v","Свой берегли бы город. Что вам — жить",0,852,0,0],["v","Век, а!.. И путь-то ведь недальний, право!",0,853,0,0],["sd","Мертвых поднимают. Процессия, в которой участвуют все, кроме хора, возвращается в прежнюю сторону. В орхестре между тем строят костер."],["scene","Четвертый музыкальный антракт","s12",4,12],["sp","Хор"],["str","Строфа"],["v","Матери радость, где ты?<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,854,0,0],["v","Матери гордость, где ты?",0,855,0,0],["v","Нет тебе места дома",0,856,0,0],["v","Меж матерей счастливых…",0,857,0,0],["v","И мне Артемида, бездетной,<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,858,0,0],["v","Больше не скажет: «Здравствуй!..»",0,960,0,1],["v","Жить-то зачем? И эту",0,960,0,0],["v","Чем я наполню пустыню?",0,961,0,0],["v","Туча теперь я в небе,",0,962,0,0],["v","Бурей гонима.",0,962,0,0],["str","Антистрофа"],["v","Семеро нас рождало,",0,963,0,0],["v","Семеро их родилось.",0,964,0,0],["v","Дети-то наши были",0,965,0,0],["v","Аргоса цвет и слава.",0,965,0,0],["v","И вот я — старуха, а сын мой,",0,966,0,0],["v","Радость, опора, где он?",0,967,0,0],["v","Нет мне меж мертвыми места,",0,967,0,0],["v","В счет не иду я под солнцем,",0,968,0,0],["v","Тенью брожу одна я",0,969,0,0],["v","В сумерках жизни…",0,970,0,1],["str","Эпод"],["v","Как его воспоминанье,",0,970,0,0],["v","В доме мне остались слезы",0,971,0,0],["v","Да венцы — седые пряди,",0,972,0,0],["v","Что печаль скосила медью,",0,973,0,0],["v","Мне остались, да напиток,",0,974,0,0],["v","Сладкий мертвым, да напевы,",0,975,0,0],["v","От которых золотые,",0,975,0,0],["v","Хмурясь, Феб уносит кудри,",0,976,0,0],["v","Да на пеплосе, к рассвету,",0,977,0,0],["v","Складки влажные, что стынут",0,978,0,0],["v","На груди, рыданий полной.",0,979,0,0],["sp","Корифей"],["v","Вот он — гроб Капанея,",0,980,0,1],["v","Глядите — вот — священный воздвигся…",0,981,0,0],["v","Дары из дворца слуги выносят…",0,982,0,0],["v","Постойте! Это кто же?",0,983,0,0],["v","Или супруга?",0,984,0,0],["v","Да, это — Эвадна, Ифитова дочь,",0,985,0,0],["v","Возле останков жертвы перуна.",0,986,0,0],["v","Ба!.. зачем же наверх идет на скалу,",0,987,0,0],["v","На выступ идет над костром? Глядите…",0,988,0,0],["v","Глядите…",0,989,4,0],["act","Действие пятое","a5","V"],["scene","Явление восьмое","s13",5,13],["sd","Те же и <span class=\"ch\" data-ch=\"evadna\">Эвадна</span>, которая в уборе невесты появляется на выступе скалы, охраняющей чертог. Костер между тем разгорается как бы ей навстречу."],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["str","Строфа"],["v","Зачем, о, зачем же огнисты",0,990,0,1],["v","У Солнца с колес летели",0,991,0,0],["v","В тот день и горели брызги?",0,992,0,0],["v","А в темном эфире следом",0,993,0,0],["v","Луна катилась, и нимф",0,994,0,0],["v","Сквозь сумрак факелы брак мой,",0,995,0,0],["v","Мой славный брак озаряли?",0,996,0,0],["v","Зачем уводил, ликуя,",0,997,0,0],["v","Меня ты с гимнами, Аргос,",0,998,0,0],["v","В чертог меднолатого мужа?",0,999,0,0],["v","И где ж он? О, где ж он? Ног я",0,1000,0,1],["v","Не слыша, сюда бежала…",0,1000,0,0],["v","Костер его где?..",0,1001,0,0],["v","Мне надо к нему, поймите,",0,1002,0,0],["v","В пламенный гроб его.",0,1003,0,0],["v","Там покончится мука,",0,1004,0,0],["v","Цепи туда я сброшу.",0,1005,0,0],["v","Смерть не та ль нам отрадна,",0,1006,0,0],["v","Если идти за другом,",0,1007,0,0],["v","Куда ему бог назначит.",0,1008,0,0],["sp","Корифей"],["v","Иль там костра не видишь ты внизу",0,1009,0,0],["v","Кронидовой святыни? Там почиет,",0,1010,0,1],["v","Испепелен перуном, Капаней.",0,1011,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["str","Антистрофа"],["v","Так вот он, предел желанный!",0,1012,0,0],["v","Иль это судьба сегодня",0,1013,0,0],["v","Со мной заодно? Отсюда",0,1014,0,0],["v","Я прыгну. Отсюда славы",0,1015,0,0],["v","Победный приму венец.",0,1016,0,0],["v","Сквозь пламя тело я с телом,",0,1017,0,0],["v","С любимым телом солью я,",0,1020,0,1],["v","На грудь его грудью лягу…",0,1020,0,0],["v","За ним и туда, убитым,",0,1021,0,0],["v","В чертог Персефоны сойду я,",0,1022,0,0],["v","Ему изменить не в силах.",0,1023,0,0],["v","О пламя! О ложе! Здравствуй!",0,1023,0,0],["v","О боги! А вы",0,1024,0,0],["v","Детям в женитьбе счастье",0,1025,0,0],["v","Дайте моим вкусить!",0,1026,0,0],["v","Жен им добрых и честных!",0,1026,0,0],["v","Сердцем, чуждым обмана,",0,1027,0,0],["v","Мужа дочери, чтобы",0,1028,0,0],["v","Верен ей был сердцем",0,1029,0,0],["v","И дома ее достоин.",0,1030,0,1],["sp","Корифей"],["v","Сюда идет отец твой престарелый.<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,1030,0,0],["v","Не чувствует еще Ифит твоих,",0,1031,0,0],["v","Не слышит слов, волнующих глубоко.",0,1032,0,0],["scene","Явление девятое","s14",5,14],["sd","Справа Ифит, белый старик со свитой. Он не видит еще дочери."],["sp","Ифит"],["v","О женщины печальные! в ваш круг",0,1033,0,0],["v","И старого не радость гонит. Двое",0,1034,0,0],["v","Детей меня заботят. Этеокла,",0,1035,0,0],["v","Кадмейцами убитого, везти",0,1036,0,0],["v","Домой готов корабль, да вот ищу я",0,1037,0,0],["v","И дочери. Без памяти вдова",0,1038,0,0],["v","Искать его бежала, Капанея, —",0,1039,0,0],["v","С ним умереть рвалася все. Ее",0,1040,0,1],["v","Мы берегли, а тут несчастье это",0,1041,0,0],["v","Недосмотрел… и вот… к вам первым я:",0,1042,0,0],["v","Не видели ль, скажите, дайте след…",0,1043,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","Что спрашивать чужих-то? Иль не видишь:",0,1044,0,0],["v","Как птица над могилой, я парю,",0,1045,0,0],["v","Как птица, только на тяжелых крыльях.",0,1046,0,0],["sp","Ифит"],["v","О ветреный ребенок! Но наряд",0,1047,0,0],["v","Так странен твой. И здесь чего ж ты ищешь?",0,1048,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","Сердить тебя боялась я, отец!",0,1050,0,1],["v","Нехорошо, чтоб ты об этом слышал.",0,1051,0,0],["sp","Ифит"],["v","О чем же я, отец, не должен знать?",0,1052,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","Судьей бы был ты в деле неискусным.",0,1053,0,0],["sp","Ифит"],["v","Но твой убор?.. К чему ж такой убор?",0,1054,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","К чему убор? Да, он надет недаром.",0,1055,0,0],["sp","Ифит"],["v","И скорбные одежды ты сняла.",0,1056,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","О да… На мне одежда новой жизни.",0,1057,0,0],["sp","Ифит"],["v","Над мужнею могилой, над костром?",0,1058,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","Победою надменная, парю я…",0,1059,0,0],["sp","Ифит"],["v","Кого же ты, скажи мне, превзошла?",0,1060,0,1],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","Всех женщин, всех, которых видит солнце.",0,1061,0,0],["sp","Ифит"],["v","Чем? Разумом иль, может, мастерством?",0,1062,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","Нет, доблестью! Деля могилу с мужем.",0,1063,0,0],["sp","Ифит"],["v","Загадка не загадка… Или бред?",0,1064,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","Я к мертвому в костер скачок готовлю.",0,1065,0,0],["sp","Ифит"],["v","О дочь моя! Здесь люди… Постыдись.",0,1066,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","Весь Аргос это слушай — так желаю.",0,1067,0,0],["sp","Ифит"],["v","Не смей, не смей… Не позволяю я…",0,1068,0,0],["sp","<span class=\"ch\" data-ch=\"evadna\">Эвадна</span>"],["v","Э… все равно… Руками не достанешь…",0,1069,0,0],["v","Как томно мне… Тебе не любо… нет…",0,1070,0,1],["v","Но любо мне и пламени героя…",0,1071,0,0],["sd","(Бросается в огонь.)"],["sp","Хор"],["sd","Увы! Женщина… Страшное ты Дело свершила!"],["sp","Ифит"],["v","Погиб, погиб я, жены, злополучный!",0,1072,0,0],["sp","Хор"],["sd","Несчастный отец Дерзкой жены… Это отчаянье Долго в глазах носить ты будешь!"],["sp","Ифит"],["v","Нет моему подобия в несчастьях.",0,1073,0,0],["sp","Хор"],["v","Старец, о старец злосчастный,",0,1074,0,0],["v","Это проклятье Эдипа — на всех его хватит,",0,1075,0,0],["v","И на тебя, и на Аргос — увы, и на нас!",0,1076,0,0],["sp","Ифит"],["v","Увы! Зачем нам не дано два раза",0,1080,0,1],["v","Быть молодым и стариться. В дому",0,1081,0,0],["v","Заметно упущенье… что ж? Обдумай —",0,1082,0,0],["v","И сладится… Лишь жизни не вернешь.",0,1083,0,0],["v","Когда бы дважды молоды мы были",0,1084,0,0],["v","И старились два раза, что не так —",0,1085,0,0],["v","Поправил бы при новом круге всяк.",0,1086,0,0],["v","Вот я, бывало, вижу, что отцом",0,1087,0,0],["v","Кто сделался, и сердце загорится,",0,1088,0,0],["v","Ну просто смерть, как сына я хотел.",0,1089,0,0],["v","А как узнаешь, каково могилу",0,1090,0,1],["v","Ребенку рыть, бог с ними и с детьми.",0,1091,0,0],["v","Вот вырастил я сына. То ли не был",0,1092,0,0],["v","Он доблестен? А вот верни его…",0,1093,0,0],["v","И что ж теперь я делать буду? Или",0,1094,0,0],["v","Назад, к себе, в пустой дворец, чтоб лучше",0,1095,0,0],["v","Почувствовать, как вымерло вокруг",0,1096,0,0],["v","Все прошлое… Пожалуй, к Капанею?",0,1097,0,0],["v","Пока жила <span class=\"ch\" data-ch=\"evadna\">Эвадна</span>, так меня",0,1098,0,0],["v","Тянуло в этот дом. Бывало, губы",0,1099,0,0],["v","То ласково к щеке моей прижмет",0,1100,0,1],["v","Иль голову руками приподымет.",0,1100,0,0],["v","Для старого отрадней нет отца,",0,1101,0,0],["v","Чем дочь его. Пускай душой я тверже",0,1102,0,0],["v","И выше сосн. Да ласки в сыне нет.",0,1103,0,0],["v","Куда-нибудь ведите… хоть обратно…",0,1103,0,0],["v","Зароюсь в темный угол, и мои",0,1104,0,0],["v","От голода погаснут скоро силы.",0,1105,0,0],["v","На что и прах сыновний собирать?",0,1106,0,0],["v","О, как я ненавижу эту старость",0,1106,0,0],["v","Согбенную… Да и себя за то,",0,1107,0,0],["v","Что с ней еще ношусь я… Как противны",0,1108,0,0],["v","Мне старики, что жадно берегут",0,1109,0,0],["v","И греют и лелеют это тело:",0,1110,0,1],["v","Хоть чуточку у смерти да урвать.",0,1110,0,0],["v","С дороги их… В могилу их. Ни пользы,",0,1111,0,0],["v","Ни радости от них… Лишь теснота.",0,1112,0,0],["sd","Его уводят направо."],["scene","Явление десятое","s15",5,15],["sd","Без Ифита. Во время слов корифея снова на орхестру выступает процессия. Отроки несут урны. <span class=\"ch\" data-ch=\"tesey\">Тесей</span> и <span class=\"ch\" data-ch=\"adrast\">Адраст</span> за ними. Матери в сопровождении служанок выступают навстречу отрокам."],["sp","Корифей"],["v","То усопших несут прах сожженных детей…",0,1113,0,0],["v","О рабыни! Опорою вы",0,1114,0,0],["v","Будьте старухе в плаче…",0,1115,0,0],["v","Ноги мои подломились.",0,1116,0,0],["v","О, не довольно ли? Сколько",0,1117,0,0],["v","Лет я жила! Сколько",0,1118,0,0],["v","Желчи пила я… Но пытка",0,1119,0,0],["v","Есть ли больней сердцу",0,1120,0,1],["v","Встретиться так с ребенком?",0,1120,0,0],["sd","Одна мать и один отрок при мимическом сопровождении остальных и женского хора."],["sp","Отрок"],["str","Строфа I"],["v","Вот оно… вот оно…",0,1121,0,0],["v","Кружечка малая",0,1122,0,0],["v","Только грузна —",0,1123,0,0],["v","Пепел отцовский в ней —",0,1123,0,0],["v","Там — все имение,",0,1124,0,0],["v","Слезы мои — и те.",0,1125,0,0],["v","О, злополучная,",0,1126,0,0],["v","О, моя мать!",0,1126,0,0],["sp","Мать"],["v","Увы мне! Увы мне!",0,1127,0,0],["v","И нее тут? И все тут?",0,1128,0,0],["v","Слезами политую",0,1129,0,0],["v","Пепла-то — горсточку…",0,1130,0,1],["v","И это герой,",0,1130,0,0],["v","Микены дививший муж.",0,1131,0,0],["sp","Отрок"],["str","Антистрофа I"],["v","Горе мне! Горе мне!",0,1131,0,0],["v","Нету родимого,",0,1132,0,0],["v","Осиротел.",0,1132,0,0],["v","Жизнь моя горькая,",0,1133,0,0],["v","Угол мой холоден,",0,1133,0,0],["v","Руку отцовскую",0,1134,0,0],["v","Больше для бодрости",0,1135,0,0],["v","Мне не сжимать.",0,1135,0,0],["sp","Мать"],["v","Увы мне! Увы мне!",0,1136,0,0],["v","Где ж муки рожденья?",0,1136,0,0],["v","И радость рожденья где?",0,1137,0,0],["v","Сын у груди моей —",0,1137,0,0],["v","Где ночи без сна?",0,1138,0,0],["v","Щека его нежная?",0,1138,0,0],["sp","Отрок"],["str","Строфа II"],["v","Дым и прах — ты, родимый!",0,1139,0,0],["v","Дым и прах — и все вы, все вы,",0,1140,0,1],["v","В пепел вас спалил костер,",0,1140,0,0],["v","Вас в эфире развевая,",0,1141,0,0],["v","Отдал темному Аиду.",0,1142,0,0],["sp","Мать"],["v","Ты слышал ли жалобу сына?",0,1143,0,0],["v","О, дай ему меч обнажить",0,1144,0,0],["v","Когда-нибудь, меч, о сын мой!",0,1145,0,0],["sp","Отрок"],["str","Антистрофа II"],["v","Так бы бог позволил это!",0,1146,0,0],["v","Месть в уме моем уж зреет.<a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,1147,0,0],["v","Не довольно ль было слез,",0,1148,0,0],["v","Не довольно ли стенаний,",0,1149,0,0],["v","Скорби этой не довольно ль?",0,1150,0,1],["sp","Мать"],["v","Ты в медных кольчугах дружины",0,1151,0,0],["v","За светлый Асоп поведешь:",0,1152,0,0],["v","Ты мститель отцовский будешь.",0,1153,0,0],["sp","Отрок"],["sd","Строфа III На тебя гляжу, отец, я будто."],["sp","Мать"],["v","Дай губам моим лицо.",0,1154,0,0],["sp","Отрок"],["v","Так с губ твоих, отец, призывы,",0,1155,0,0],["v","Верно, ветер схоронил… их нет.",0,1156,0,0],["sp","Мать"],["v","Матери стенанья он оставил,",0,1157,0,0],["v","А тебе — воспоминаний боль.",0,1158,0,0],["sp","Отрок"],["sd","Антистрофа III Я совсем под этой ношей гибну…"],["sp","Мать"],["v","Дай к груди прижать остывший прах!",0,1160,0,1],["sp","Отрок"],["v","Страшное произнесла ты слово:",0,1161,0,0],["v","Глубоко ты сердце ранишь мне.",0,1162,0,0],["sp","Мать"],["v","Ты уходишь? Значит, больше светом,",0,1163,0,0],["v","Светом глаз твоих я не упьюсь?..",0,1164,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О матери аргосские, и ты,",0,1165,0,0],["v","О царь <span class=\"ch\" data-ch=\"adrast\">Адраст</span>, в руках детей, которым",0,1166,0,0],["v","Вернули мы тела отцов, пусть прах",0,1167,0,0],["v","Тот славный остается, дар <span class=\"ch\" data-ch=\"tesey\">Тесея</span>",0,1168,0,0],["v","И города Паллады. Эту милость",0,1169,0,0],["v","Принявши, сохраните, чтоб она",0,1170,0,1],["v","Из памяти не вышла. Дети ж пусть",0,1171,0,0],["v","Передадут в потомство, чем Афинам",0,1172,0,0],["v","Обязаны… А как почтили вас,",0,1173,0,0],["v","Свидетели теперь — Кронид и боги…",0,1174,0,0],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Мы хорошо, Тесей, запомним все,",0,1175,0,0],["v","Что сделал ты для Аргоса в годину",0,1176,0,0],["v","Тяжелую. Запомним навсегда.",0,1177,0,0],["v","Иль то не долг — ценить благодеянья?",0,1178,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","О чем-нибудь вы просите еще?",0,1180,0,1],["sp","<span class=\"ch\" data-ch=\"adrast\">Адраст</span>"],["v","Нет, и прощай. Мои благословенья",0,1180,0,0],["v","И городу и славному вождю.",0,1181,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Благодарю и отвечаю тем же.",0,1182,0,0],["v","Простите же, прости и ты, Адраст…",0,1183,0,0],["scene","Явление одиннадцатое","s16",5,16],["act","Исход","a6",""],["sd","На альтане показывается Афина. Готовившиеся покинуть орхестру останавливаются."],["sp","Афина"],["v","Сперва, Тесей, исполни речь Афины,",0,1184,0,0],["v","Для города полезную. Ты прах",0,1185,0,0],["v","Не слишком ли отдать поторопился",0,1185,0,0],["v","Аргосцам этим юным, чтоб они",0,1186,0,0],["v","Перенесли к себе его? Сначала,",0,1187,0,0],["v","Взамен трудов народа и своих,",0,1188,0,0],["v","Ты клятву с них возьми. Клянется ж пусть<a class=\"nr\" href=\"#n-k40\" data-n=\"k40\" aria-label=\"Примечание 40\">40</a>",0,1189,0,0],["v","<span class=\"ch\" data-ch=\"adrast\">Адраст</span> — он царь и за страну в ответе.",0,1190,0,1],["v","А клятва в том, что Аргос никогда",0,1190,0,0],["v","В афинские не вторгнется пределы,",0,1191,0,0],["v","И если б кто вступить задумал, он",0,1192,0,0],["v","С оружием в руках мешать обязан.",0,1193,0,0],["v","А преступи он клятву и на вас",0,1193,0,0],["v","Пойди войной — так самому ж на гибель.",0,1194,0,0],["v","Пусть в этом поклянется. Дальше — кровь",0,1195,0,0],["v","Из жертвенных животных соберешь ты",0,1196,0,0],["v","В особенный котел. Тебе котел",0,1196,0,0],["v","Тот укажу. Когда от пепла Трои",0,1197,0,0],["v","Алкид к делам переходил иным,",0,1198,0,0],["v","Он дал тебе добычу, чтоб ее",0,1199,0,0],["v","Ты посвятил на очаге Дельфийском.",0,1200,0,1],["v","Треножник был то медный. До сих пор",0,1200,0,0],["v","Не отсылал его ты. В эти недра",0,1201,0,0],["v","Дай овчей крови стечь, а клятву ты",0,1202,0,0],["v","На меди начертаешь. Аполлону",0,1202,0,0],["v","Затем ты дар Геракла перешлешь,",0,1203,0,0],["v","И в памяти у эллинов присяга",0,1204,0,0],["v","Останется Адрастова прочней",0,1204,0,0],["v","Закреплена Дельфийцем. Меч, которым",0,1205,0,0],["v","Овец колол для договорной жертвы,",0,1206,0,0],["v","Зарыть потом ты должен, где семи",0,1206,0,0],["v","Костерных груд чернеть остались угли,",0,1207,0,0],["v","Чтоб, если на Афины дерзновенно",0,1208,0,0],["v","Аргосец встал, — поднявшись, длинный меч",0,1208,0,0],["v","Прогнал его смятенным. После кости",0,1209,0,0],["v","Спаленные отдашь им. Поле то ж,",0,1210,0,1],["v","Где их тела пожрало пламя, богу",0,1210,0,0],["v","Ты посвятишь: пути скрестились там,",0,1211,0,0],["v","Но главная ведет дорога к Истму.",0,1212,0,0],["v","Все для тебя, <span class=\"ch\" data-ch=\"tesey\">Тесей</span>.",0,1213,0,0],["v","Теперь аргосцам:",1,1213,0,0],["v","Вы — отроки, но станете мужи,",0,1214,0,0],["v","И Фивы будут ваши. И вождями",0,1215,0,0],["v","Дано вам быть, Эгиалей отца",0,1216,0,0],["v","Заменит, а Тидид из Калидона",0,1217,0,0],["v","Придет и зваться будет Диомед.",0,1218,0,0],["v","Но подождать придется, чтобы щеки",0,1219,0,0],["v","Покрылись первым пухом, и данайцев",0,1220,0,1],["v","Не поднимайте раньше. Точно львы,",0,1220,0,0],["v","На город вы накинетесь. И будет",0,1221,0,0],["v","Не иначе, как я сказала. Вы",0,1222,0,0],["v","Получите названье «Эпигоны»,",0,1223,0,0],["v","И гимны вас прославят по лицу",0,1224,0,0],["v","Эллады: так, по милости бессмертных,",0,1225,0,0],["v","Ваш будет подвиг дерзкий знаменит.",0,1225,0,0],["sp","<span class=\"ch\" data-ch=\"tesey\">Тесей</span>"],["v","Владычица Афина, я из воли<a class=\"nr\" href=\"#n-k41\" data-n=\"k41\" aria-label=\"Примечание 41\">41</a>",0,1226,0,0],["v","Твоей не выйду. Ты всегда на путь",0,1227,0,0],["v","Меня прямой выводишь. Я присягой",0,1228,0,0],["v","Свяжу царя аргосского. Лишь ты",0,1229,0,0],["v","Не оставляй советом нас. Твоей",0,1230,0,1],["v","Мы милостью благополучны, Дева.",0,1231,0,0],["sp","Хор"],["v","Пойдем же, Адраст, и клятву",0,1232,0,0],["v","Пред царем и Афинами дашь ты.",0,1233,0,0],["v","Велик был их труд и честен.",0,1234,0,0],["sd","Все уходят."],["h1","Комментарий","comm"],["p","Так как сюжетная ситуация трагедии — спор афинян с фиванцами о выдаче трупов — очень близко напоминает исторический факт, связанный с поражением афинского войска у беотийского города Делия поздней осенью 424 г. (см. Фуки- дид, IV, 76-77, 89 — 101), то не вызывает сомнения, что «Умоляющие» созданы под свежим впечатлением этого события вскоре после 424 г. В более точной датировке исследователи несколько расходятся: одни относят постановку трагедии к весне 422 г., другие — к весне 420 г.; так или иначе, трагедия создана на исходе первого десятилетия Пелопоннесской войны, когда Афины активно искали союза с Аргосом, чье влияние на Пелопоннесе они могли бы противопоставить гегемонии Спарты, в то время как сам Аргос вел политику выжидания, чтобы решить, к какой из двух сторон ему выгоднее присоединиться."],["p","По содержанию «Умоляющие» как бы примыкают к написанным много позднее «Финикиянкам»: поход семерых вождей против Фив закончился поражением нападавших, и теперь фиванцы запрещают хоронить не только тело Полиника, но и всех павших вместе с ним аргосцев. Конфликт получал разрешение только с помощью афинян, то ли сумевших добиться разумного компромисса между беотийцами и аргосцами, то ли вынудивших Фивы силой оружия выдать трупы погибших. Этот чисто аттический вариант сказания был разработан до Еврипида на афинской сцене Эсхилом в его трагедии «Элевсинцы» (не сохранилась)."],["p","Текст перевода печатается по наборной рукописи (РО РГБ, фонд Сабашниковых)."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"],["note","k40"],["note","k41"]],"n":{"k1":["Ст. 1. Элевсис (Элевсин)","одно из древнейших поселений в Аттике; здесь с незапамятных времен существовал культ Деметры и справлялись знаменитые Элевсинские мистерии (см. ст. 173)."],"k2":["Ст. 5-7. Трезен","см. «Ипполит», Локсий — Аполлон, Пандионид — Тесей."],"k3":["Ст. 30. …где в первый раз…","По аттическому преданию, Деметра научила афинского царевича Триптолема искусству хлебопашества."],"k4":["Ст. 132-150. См.: «Финикиянки», ст. 409","423."],"k5":["Ст. 158. Амфиарай был против.","Амфиарай, обладавший даром провидения, настойчиво отклонял Адраста от похода на Фивы, но не смог его переубедить."],"k6":["Ст. 179","После этого стиха в рукописях, очевидно, пропуск; Адраст объяснял, почему ему трудно увлечь своей речью Тесея: на уме у него — сплошное горе, и в этих условиях трудно думать о красоте слов; ведь и поэту нужно душевное спокойствие в момент творчества."],"k7":["Ст. 184. Край Пелопа был на пути…","Недосмотр переводчика. «Край Пелопа», если им считать Спарту (см. ст. 187), — южнее Аргоса и никак не мог лежать на пути оттуда в Афины. В оригинале мысль другая: почему Адраст. в своих просьбах обошел спартанцев?"],"k8":["Ст. 201-213. Хвала тому бессмертному…","Согласно Эсхилу, этим богом, открывшим людям путь к осмысленной жизни, был Прометей (см. трагедию «Прометей прикованный», ст. 441-506)."],"k9":["Ст. 263. …сын Пелопа…","Перед этим стихом в рукописях опять утеряно несколько стихов. Смысл их, вероятно, следующий: если тебя не беспокоит престиж твоего города и божественные законы, то помоги нам как родне, — ведь Питфей, твой дед по матери, был сыном Пелопа (см. примеч. к «Гераклидам», ст. 36). Однако из текста не следует, что слова эти (и до конца монолога) обращены к Эфре. Скорее, их адресатом является сам Тесей. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Гераклиды», Ст. 36. В них кровь одна с Геракловым потомством….</b> Еврипид следует здесь тому варианту мифологической генеалогии, по которому Алкмена, мать Геракла, и Эфра, мать Тесея, являлись обе внучками Пелопа. В свою очередь, Алкмена и Еврисфей являются двоюродными братом и сестрой, так как их отцы — сыновья Персея, а матери — дочери Пелопа (см. также ст. 207-212, 987 и сл.).</span><!--/xn-->"],"k10":["Ст. 293-296","Однострочная стихомифия передана Анненским двустрочными репликами."],"k11":["Ст. 316. …с диким вепрем он не боялся драться…","По дороге из Трезена в Афины юный Тесей убил в окрестностях Коринфа дикую свинью."],"k12":["Ст. 349-357. Только воля афинского народа…","Апеллируя к народному собранию, Тесей поступает так же, как эсхиловский Пеласг в «Умоляющих», ст. 397-401:<br>Сказал: решенья не приму — хотя бы смел, -<br>Не выслушав народа. Никогда пускай<br>Мне в городе не скажут: в горький час беды<br>Почтил он пришлых, но сгубил родной народ.<br>(Перевод Адр. Пиотровского)"],"k13":["Ст. 371. Край Инахов","Аргос."],"k14":["Ст. 392. Пляска красоты","то есть Каллихор, священный источник в Элевсине."],"k15":["Ст. 412-425","Доводы, почерпнутые из арсенала антидемократической пропаганды афинских олигархов."],"k16":["Ст. 470. Разорвав заклятие повязок и ветвей.","То есть не обращая внимания на ветви, обвитые шерстяными нитями, — атрибут молящих о защите."],"k17":["Ст. 496-499. Капаней.","Об угрозах Капанея и его гибели см.: «Финикиянки», ст. 179-189,1127-1132."],"k18":["Ст. 500. А не сама ль земля…","Амфиарая с его колесницей, разверзшись, поглотила земля. См. ст. 925-927."],"k19":["Ст. 517-563","Ответ Тесея почти равен по объему речи глашатая, ст. 465-510 (ср. примеч. к «Медее», ст. 465-575). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 465-575.</b> Медея и Ясон обмениваются в споре (агоне) почти равными по объему речами, причем каждый из них излагает в строгом порядке доводы, которые должны подтвердить его правоту, и завершает свою речь кратким резюме общего характера. Ср. вступительную статью, с. 26.</span><!--/xn-->"],"k20":["Ст. 533 сл. …Дыхание","в эфир, а тело — в землю. — Еврипид воспроизводит широко распространенное в V в. до н. э. убеждение, что душа человека после его смерти растворяется в эфире. Эту формулу находим даже в официальном документе — надписи, перечисляющей имена афинян, павших в 432 г. под Потидеей: «Эфир принял души, а земля — тела следующих граждан…»"],"k21":["Ст. 571. Асоп","река, протекающая по фиванской равнине."],"k22":["Ст. 578. Нивы Спиртов («посеянных»)","то есть фиванцев, чьи предки родились из зубов дракона, посеянных Кадмом."],"k23":["Ст. 654-660","и 675-718. В описании сражения Еврипид соединяет картину «гомеровского» боя с колесниц с современной ему практикой ополчения гоплитов."],"k24":["Ст. 655. Йемен","река на фиванской равнине."],"k25":["Ст. 659. Паралии","население прибрежной области в Аттике."],"k26":["Ст. 663. Амфиам","см. примеч. к «Гераклу», ст. 27-34. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Геракл», Ст. 27-34.</b> Мифологическая генеалогия знала фиванского царя Лика, чья супруга Дирка (Диркея) всячески мучила свою племянницу Антиопу, мать божественных близнецов Амфиона и Зета; последние, выросши, отплатили Дирке за издевательства над их матерью, а Лика свергли с престола. О втором Лике и его вмешательстве в мятеж, якобы разгоревшийся в Фивах при Креонте, см. вступительную заметку к примечаниям.</span><!--/xn-->"],"k27":["Ст. 713. Кранайцы","афиняне, потомки легендарного героя Краная."],"k28":["Ст. 759. Элевферы","селение в предгорьях Киферона со стороны Аттики."],"k29":["Ст. 763. Как? Сам Тесей…","Реплика, пропущенная в рукописи и восстанавливаемая издателями по смыслу."],"k30":["Ст. 797",", ремарка. Из семи носилок двое без мертвых — потому что Адраст остался жив, а Амфиарай живым был принят землей."],"k31":["Ст. 798-810","Строфа II построена в оригинале, как и антистрофа II, в чередовании симметричных реплик Адраста и хора. Вплоть до ст. 838 порядок стихов в переводе нарушен. Здесь восстановлено их расположение по оригиналу."],"k32":["Ст. 846-854","Эти стихи обычно расценивают как полемику с Эсхилом, который дал в центральной сцене «Семерых против Фив» (ст. 375-676) характеристику семи вождей, нападавших на город, и семи фиванцев, выставленных против них. Но о самом сражении Эсхил в «Семерых» как раз ограничивается очень кратким сообщением, последующие же слова Тесея («ну кто, спрошу, видал…») заставляют видеть в его словах скорее критику эпических повествований о поединках отдельных героев — такие рассказы и в самом деле потеряли смысл в эпоху массовых сражений V в."],"k33":["Ст. 860-932","Здесь несомненна трактовка семерых нападающих, прямо противоположная традиции, которой и сам Еврипид будет отчасти следовать в «Финикиянках», ст. 1113-1140. Причину такой перемены понять нетрудно: Тесей, мотивирующий свое выступление в защиту тел аргосцев благочестием, не мог бы этого сделать, если бы погибшие были охарактеризованы как наглые и надменные насильники и безбожники."],"k34":["Ст. 871. Этеокл","аргосец, сын Ифита (см. ст. 1037 сл.), которого не следует смешивать с его тезкой Этеоклом, сыном Эдипа."],"k35":["Ст. 892. Метек","не имеющий полных гражданских прав."],"k36":["Ст. 909. Мои слова усвоив…","Адраст характеризует только пятерых из семи вождей, так как судьба Амфиарая (сына Оилея) и Полиника известна самому Тесею(ст. 925-931)."],"k37":["Ст. 935. Горит один…","Поскольку молния являлась атрибутом Зевса, тело человека, сраженного ею, считалось священным и подлежало захоронению с особыми почестями."],"k38":["Ст. 1026-1030","В оригинале текст сильно испорчен, и перевод дается предположительно."],"k39":["Ст. 1144. Месть в уме моем уж зреет.","Намек на поход эпигонов, которым суждено в следующем поколении разорить Фивы. Ср. ст. 1150-1152."],"k40":["Ст. 1188-1195. …Ты клятву с них возьми.","Политическая ситуация конца 20-х годов V в. проецируется в легендарное прошлое, так же как это было в «Орестее» Эсхила («Евмениды», ст. 762-774), где Орест клянется в вечной верности Аргоса Афинам."],"k41":["Ст. 1214-1226","Афина излагает сюжет послегомеровской поэмы «Эпигоны», повествовавшей о походе детей погибших на Фивы; на ту же тему и под тем же заголовком была написана трагедия Эсхила (не сохранилась). Эгиалей — сын Адраста."]},"mainEnd":1834,"c":[{"id":"tesey","name":"Тесей","role":"Царь Афин","intro":"Идеальный правитель демократических Афин.","arc":"Тесей сначала отказывает Адрасту, осуждая его безрассудную войну, но мать убеждает его защитить закон об их погребении. Он отстаивает перед фиванским герольдом свободу, а после победы сам омывает тела павших.","st":[{"i":571,"p":31,"l":"Пролог · явление второе","t":"Отказ и согласие","d":"Отказывает Адрасту, но Эфра убеждает его вступиться за обычай погребения.","c":"Выбор в пользу священного закона.","k":true},{"i":885,"p":48,"l":"Действие второе · явление четвертое","t":"Спор с герольдом","d":"Отвечает фиванскому вестнику: город свободен, правит народ, а не один.","c":"","k":false},{"i":1167,"p":64,"l":"Действие третье · явление шестое","t":"Победа","d":"Вестник рассказывает о победе Тесея, который не стал разорять Фивы и сам похоронил павших.","c":"","k":false},{"i":1762,"p":96,"l":"Действие пятое · явление десятое","t":"Прах героев","d":"Передаёт прах сыновьям павших и берёт с аргосцев обещание помнить благодеяние.","c":"","k":false}],"gen":"Тесей"},{"id":"adrast","name":"Адраст","role":"Царь Аргоса","intro":"Царь, приведший к Фивам семерых вождей и оставшийся в живых.","arc":"Адраст — виновник поражения, который признаёт свою вину. Его надгробная речь о павших вождях — одна из самых любопытных в трагедии.","st":[{"i":571,"p":31,"l":"Пролог · явление второе","t":"Мольба","d":"Просит Тесея помочь вернуть тела павших.","c":"","k":false},{"i":1433,"p":78,"l":"Действие четвертое · явление седьмое","t":"Надгробная речь","d":"По просьбе Тесея вспоминает о каждом из павших вождей.","c":"","k":true}],"gen":"Адраст"},{"id":"efra","name":"Эфра","role":"Мать Тесея","intro":"Мать, убеждающая сына в справедливости.","arc":"Эфра открывает трагедию и в решающий момент становится голосом разума и благочестия.","st":[{"i":61,"p":3,"l":"Пролог · явление первое","t":"Пролог","d":"Матери павших окружили её у алтаря Деметры в Элевсине.","c":"","k":false},{"i":571,"p":31,"l":"Пролог · явление второе","t":"Убеждает сына","d":"Уговаривает Тесея помочь аргосским матерям.","c":"","k":true}],"gen":"Эфра"},{"id":"evadna","name":"Эвадна","role":"Вдова Капанея","intro":"Вдова, бросающаяся в погребальный костёр мужа.","arc":"Эвадна — образ безграничной верности: в праздничном наряде она взбирается на скалу и бросается в костёр мужа на глазах отца.","st":[{"i":1649,"p":90,"l":"Действие пятое · явление девятое","t":"Прыжок в костёр","d":"Отвергает мольбы отца Ифита и бросается в пламя.","c":"","k":true}]}]};
